-- =====================================================================
-- 093 — Perfil completo + farmacologia de 26 fármacos (lote 2)
-- ---------------------------------------------------------------------
-- Perfis (drug_profiles, padrão 090) E farmacologia (drug_pharmacology,
-- padrão 088/091/092) dos 26 fármacos seguintes por nº de pares na BD,
-- todos sem perfil e sem farmacologia (confirmado por consulta read-only).
-- Fontes (citadas por linha):
--   • 22 fármacos: secções INDICATIONS AND USAGE, ADVERSE REACTIONS,
--     CONTRAINDICATIONS, WARNINGS AND PRECAUTIONS + secção 12 CLINICAL
--     PHARMACOLOGY dos rótulos aprovados DailyMed (setIDs validados);
--   • pseudoefedrina, dextrometorfano, difenidramina: rótulos OTC DailyMed
--     (formato Drug Facts — não têm secção 12) + farmacocinética por
--     fontes PubMed (citadas por linha);
--   • artesunato-amodiaquina: SmPC WHO-prequalificada (artesunate/
--     amodiaquine, Cipla/MA102 — secções 4.1, 4.3, 4.4, 4.8 e 5.2).
-- Conteúdo autoral (não copiado), ancorado nos números das fontes.
-- Idempotente: ON CONFLICT (drug_id) DO NOTHING — reaplicar é seguro.
-- Padrão 7.6 (JOIN ON d.slug = v.slug). Aplicar na ordem 079 → 093.
-- =====================================================================

INSERT INTO public.drug_profiles
  (drug_id, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
   indications_pt, indications_en, side_effects_pt, side_effects_en,
   precautions_pt, precautions_en, source_pt, source_en, status)
SELECT d.id, v.overview_public_pt, v.overview_public_en, v.overview_pro_pt, v.overview_pro_en,
       v.indications_pt, v.indications_en, v.side_effects_pt, v.side_effects_en,
       v.precautions_pt, v.precautions_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('alendronato',
   'O alendronato é um medicamento (bifosfonato) usado para tratar e prevenir a osteoporose, tornando os ossos mais fortes e reduzindo o risco de fraturas. Toma-se normalmente uma vez por semana, em jejum, com um copo de água, e é preciso permanecer de pé ou sentado durante pelo menos 30 minutos depois.',
   'Alendronate is a medicine (bisphosphonate) used to treat and prevent osteoporosis, making bones stronger and reducing the risk of fractures. It is usually taken once a week, on an empty stomach, with a glass of water, and you must remain upright for at least 30 minutes afterwards.',
   'Bifosfonato antirreabsortivo (amino-bifosfonato) que inibe a atividade dos osteoclastos e reduz a remodelação óssea, aumentando a massa óssea e reduzindo a incidência de fraturas vertebrais e do colo do fémur. Indicado no tratamento e prevenção da osteoporose pós-menopáusica, na osteoporose induzida por glucocorticóides e na doença de Paget do osso. Absorção oral mínima (cerca de 0,6%), fortemente reduzida por alimentos e bebidas — daí as instruções rigorosas de toma em jejum.',
   'Antiresorptive bisphosphonate (amino-bisphosphonate) that inhibits osteoclast activity and reduces bone turnover, increasing bone mass and reducing the incidence of vertebral and hip fractures. Indicated for the treatment and prevention of postmenopausal osteoporosis, glucocorticoid-induced osteoporosis and Paget disease of bone. Oral absorption is minimal (about 0.6%) and strongly reduced by food and beverages — hence the strict instructions for dosing on an empty stomach.',
   E'Tratamento da osteoporose em mulheres pós-menopáusicas (aumenta a massa óssea e reduz fraturas da anca e da coluna).\nPrevenção da osteoporose pós-menopáusica.\nAumento da massa óssea em homens com osteoporose.\nTratamento da osteoporose induzida por glucocorticóides (em doentes com dose diária equivalente a 7,5 mg ou mais de prednisolona e baixa densidade óssea).\nTratamento da doença de Paget do osso.',
   E'Treatment of osteoporosis in postmenopausal women (increases bone mass and reduces hip and spine fractures).\nPrevention of postmenopausal osteoporosis.\nTreatment to increase bone mass in men with osteoporosis.\nTreatment of glucocorticoid-induced osteoporosis (in patients receiving a daily dose equivalent to 7.5 mg or more of prednisolone with low bone mineral density).\nTreatment of Paget disease of bone.',
   E'Dor abdominal, regurgitação ácida, obstipação, diarreia, dispepsia e náuseas (os mais frequentes, ≥3%).\nDor musculoesquelética.\nIrritação do esófago — dor ou dificuldade ao engolir, dor retroesternal: interromper e procurar ajuda.\nCansaço, tonturas ou cefaleias.\nRaramente: úlcera esofágica, osteonecrose da mandíbula, fraturas atípicas do fémur, hipocalcemia.',
   E'Abdominal pain, acid regurgitation, constipation, diarrhoea, dyspepsia and nausea (most common, ≥3%).\nMusculoskeletal pain.\nOesophageal irritation — pain or difficulty swallowing, retrosternal pain: stop and seek help.\nFatigue, dizziness or headache.\nRarely: oesophageal ulcer, osteonecrosis of the jaw, atypical femoral fractures, hypocalcaemia.',
   E'Tomar em jejum, com água simples, pelo menos 30 minutos antes da primeira refeição, bebida ou medicamento do dia; não deitar durante 30 minutos.\nCafé, sumo de laranja ou outras bebidas reduzem muito a absorção — tomar apenas com água.\nAssegurar aporte adequado de cálcio e vitamina D.\nInformar o médico se tiver dificuldade em engolir, azia, doença esofágica ou doença renal.\nEvitar em caso de hipocalcemia não corrigida ou alterações graves do esófago.',
   E'Take on an empty stomach with plain water at least 30 minutes before the first food, beverage or medicine of the day; do not lie down for 30 minutes.\nCoffee, orange juice or other beverages greatly reduce absorption — take only with water.\nEnsure adequate calcium and vitamin D intake.\nTell your doctor if you have difficulty swallowing, heartburn, oesophageal disease or kidney disease.\nAvoid if you have uncorrected hypocalcaemia or severe oesophageal disorders.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Alendronato sódico: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ffdd2496-d253-419b-85a6-8c615f7545f1',
   'DailyMed/FDA (NIH/NLM) — approved Alendronate sodium label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ffdd2496-d253-419b-85a6-8c615f7545f1'),

  ('alopurinol',
   'O alopurinol é um medicamento que reduz a quantidade de ácido úrico no sangue. É usado para tratar a gota e prevenir as suas crises, bem como os cálculos renais de ácido úrico. Os seus efeitos demoram algumas semanas a instalar-se e a dose é ajustada pelo médico.',
   'Allopurinol is a medicine that lowers the amount of uric acid in the blood. It is used to treat gout and prevent its flares, as well as uric acid kidney stones. Its effects take a few weeks to develop and the dose is adjusted by your doctor.',
   'Inibidor da xantina-oxidase, a enzima que converte as xantinas em ácido úrico; reduz a uricemia e a uricúria, prevenindo crises de gota, tofos, destruição articular, litíase úrica e nefropatia. Também usado como proteção contra a síndrome de lise tumoral durante quimioterapia citotóxica. A hipersensibilidade (SDRIFE/DRESS, SJS/NET) é a reação mais temida — risco maior nos primeiros meses, na IR, com diuréticos tiazídicos e em portadores do alelo HLA-B*5801.',
   'Xanthine oxidase inhibitor, the enzyme that converts xanthines to uric acid; lowers serum and urinary uric acid, preventing gout flares, tophi, joint destruction, uric acid lithiasis and nephropathy. Also used for protection against tumour lysis syndrome during cytotoxic chemotherapy. Hypersensitivity (DRESS, SJS/TEN) is the most feared reaction — greater risk in the first months, in renal impairment, with thiazide diuretics and in carriers of the HLA-B*5801 allele.',
   E'Tratamento de adultos com sinais e sintomas de gota primária ou secundária (crises agudas, tofos, destruição articular, litíase úrica e/ou nefropatia).\nTratamento de crianças e adultos com nefropatia por ácido úrico.\nTratamento de doentes com litíase úrica recorrente.\nPrevenção da síndrome de lise tumoral em doentes sob quimioterapia (uso oncológico).',
   E'Management of adults with signs and symptoms of primary or secondary gout (acute attacks, tophi, joint destruction, uric acid lithiasis and/or nephropathy).\nManagement of paediatric and adult patients with uric acid nephropathy.\nManagement of patients with recurrent uric acid stones.\nPrevention of tumour lysis syndrome in patients receiving chemotherapy (oncological use).',
   E'Náuseas, diarreia e elevação das provas de função hepática (as mais frequentes, >1%).\nErupção cutânea — pode ser o primeiro sinal de reação grave de hipersensibilidade: parar e procurar ajuda imediatamente.\nCrises de gota no início do tratamento (prevenir com colchicina ou AINE durante os primeiros meses).\nSonolência ou tonturas (afetam a condução).\nRaramente: DRESS, síndrome de Stevens-Johnson, mielossupressão, nefrotoxicidade, hepatotoxicidade.',
   E'Nausea, diarrhoea and elevation of liver function tests (most common, >1%).\nSkin rash — may be the first sign of a severe hypersensitivity reaction: stop and seek help immediately.\nGout flares at the start of treatment (prevent with colchicine or an NSAID during the first months).\nDrowsiness or dizziness (affect driving).\nRarely: DRESS, Stevens-Johnson syndrome, myelosuppression, nephrotoxicity, hepatotoxicity.',
   E'Parar o medicamento ao primeiro sinal de erupção cutânea ou outros sinais de hipersensibilidade — reações graves podem ser fatais.\nBeber bastante líquido e manter a urina diluída.\nDose ajustada à função renal; reduzir na insuficiência renal.\nRisco acrescido de hipersensibilidade com diuréticos tiazídicos e na IR; teste HLA-B*5801 antes de iniciar em populações de risco (ex.: chineses Han, tailandeses).\nCuidado com a condução no início (sonolência).\nAjustar a dose de azatioprina/mercaptopurina quando usado em conjunto (inibição da xantina-oxidase).',
   E'Stop the medicine at the first sign of skin rash or other hypersensitivity features — severe reactions can be fatal.\nDrink plenty of fluids and keep urine diluted.\nDose adjusted to renal function; reduce in renal impairment.\nIncreased risk of hypersensitivity with thiazide diuretics and in renal impairment; HLA-B*5801 screening before starting in at-risk populations (e.g. Han Chinese, Thai).\nTake care when driving early in treatment (drowsiness).\nAdjust azathioprine/mercaptopurine dose when used together (xanthine oxidase inhibition).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Alopurinol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=583df4b8-a1d4-01ed-e063-6394a90af007',
   'DailyMed/FDA (NIH/NLM) — approved Allopurinol label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=583df4b8-a1d4-01ed-e063-6394a90af007'),

  ('apixabano',
   'O apixabano é um anticoagulante (dilui o sangue) usado para prevenir coágulos e AVC em pessoas com fibrilhação auricular, e para tratar e prevenir tromboses e embolias. Toma-se por via oral, com ou sem alimentos. Como qualquer anticoagulante, aumenta o risco de hemorragia.',
   'Apixaban is an anticoagulant (blood thinner) used to prevent clots and stroke in people with atrial fibrillation, and to treat and prevent deep vein thrombosis and pulmonary embolism. It is taken orally, with or without food. Like any anticoagulant, it increases the risk of bleeding.',
   'Anticoagulante oral de ação direta, inibidor seletivo e reversível do fator Xa. Indicado na prevenção de AVC e embolia sistémica na fibrilhação auricular não valvular, no tratamento e prevenção de TVP/EP e na profilaxia após artroplastia eletiva da anca ou joelho. Eliminação mista (renal ~27%, fecal/biliar), sem necessidade de monitorização de rotina da coagulação. Interage com inibidores/indutores fortes do CYP3A4 e da glicoproteína-P.',
   'Direct-acting oral anticoagulant, selective and reversible inhibitor of factor Xa. Indicated for stroke and systemic embolism prevention in non-valvular atrial fibrillation, treatment and prevention of DVT/PE and prophylaxis after elective hip or knee arthroplasty. Mixed elimination (renal ~27%, faecal/biliary), no routine coagulation monitoring required. Interacts with strong CYP3A4 and P-glycoprotein inhibitors/inducers.',
   E'Redução do risco de AVC e embolia sistémica em adultos com fibrilhação auricular não valvular.\nTratamento da trombose venosa profunda (TVP) e prevenção da embolia pulmonar (EP).\nTratamento da EP e prevenção da recorrência de TVP/EP.\nProfilaxia da TVP após artroplastia eletiva da anca ou do joelho (adultos).',
   E'Reduction of the risk of stroke and systemic embolism in adult patients with non-valvular atrial fibrillation.\nTreatment of deep vein thrombosis (DVT) and prevention of pulmonary embolism (PE).\nTreatment of PE and prevention of recurrent DVT/PE.\nProphylaxis of DVT following elective hip or knee replacement (adults).',
   E'Hemorragia (a reação adversa mais comum, >1% nos adultos) — nariz, gengivas, nódoas negras, sangue na urina ou fezes.\nNáuseas e anemia.\nNas crianças (uso específico): cefaleias, vómitos e hemorragia menstrual intensa (≥10%).\nProcurar ajuda urgente perante hemorragia anormal, vómitos com sangue ou fezes escuras.',
   E'Bleeding (the most common adverse reaction, >1% in adults) — nose, gums, bruises, blood in urine or stools.\nNausea and anaemia.\nIn children (specific use): headache, vomiting and heavy menstrual bleeding (≥10%).\nSeek urgent help for abnormal bleeding, vomiting blood or dark stools.',
   E'Informar sempre o médico sobre qualquer outro medicamento, especialmente anti-inflamatórios, aspirina, outros anticoagulantes ou antifúngicos/antibacterianos (ex.: cetoconazol, rifampicina).\nNão interromper sem indicação — o risco de trombose aumenta.\nAntes de cirurgias ou procedimentos invasivos (incluindo punção lombar), informar a equipa.\nSe notar hemorragia invulgar ou prolongada, procurar ajuda médica.\nManter o horário regular das tomas (2 vezes ao dia, exceto indicação contrária).',
   E'Always tell your doctor about any other medicine, especially anti-inflammatories, aspirin, other anticoagulants or antifungals/antibacterials (e.g. ketoconazole, rifampicin).\nDo not stop without advice — the risk of thrombosis increases.\nBefore surgery or invasive procedures (including spinal puncture), inform the team.\nSeek medical help if you notice unusual or prolonged bleeding.\nKeep a regular dosing schedule (twice daily unless otherwise advised).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Apixabano (ELIQUIS): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a454cd24-0c6d-46e8-b1e4-197388606175',
   'DailyMed/FDA (NIH/NLM) — approved Apixaban (ELIQUIS) label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a454cd24-0c6d-46e8-b1e4-197388606175'),

  ('atazanavir',
   'O atazanavir é um medicamento antirretroviral usado no tratamento da infeção por VIH, sempre em associação com outros medicamentos. É geralmente bem tolerado, mas pode causar icterícia (pele e olhos amarelados) devido ao aumento da bilirrubina, que não é prejudicial mas deve ser vigiada.',
   'Atazanavir is an antiretroviral medicine used to treat HIV infection, always in combination with other medicines. It is generally well tolerated, but can cause jaundice (yellow skin and eyes) due to raised bilirubin, which is not harmful but should be monitored.',
   'Inibidor da protease do VIH-1 (IP), usado em associação com outros antirretrovirais no tratamento da infeção por VIH-1 em adultos e crianças ≥3 meses. Farmacocinética não linear com os alimentos a aumentarem a exposição; pode ser potenciado com ritonavir ou cobicistate. Hiperbilirrubinémia indireta (icterícia) é um efeito de classe frequente; prolonga o intervalo PR; metabolizado pelo CYP3A4 (inibidor moderado).',
   'HIV-1 protease inhibitor (PI), used in combination with other antiretrovirals for the treatment of HIV-1 infection in adults and children ≥3 months. Non-linear pharmacokinetics with food increasing exposure; may be boosted with ritonavir or cobicistat. Indirect hyperbilirubinaemia (jaundice) is a frequent class effect; prolongs the PR interval; metabolised by CYP3A4 (moderate inhibitor).',
   E'Tratamento da infeção por VIH-1 em adultos, em associação com outros agentes antirretrovirais.\nTratamento da infeção por VIH-1 em doentes pediátricos com 3 meses ou mais e peso ≥5 kg, em associação.',
   E'Treatment of HIV-1 infection in adults, in combination with other antiretroviral agents.\nTreatment of HIV-1 infection in paediatric patients aged 3 months and older weighing at least 5 kg, in combination.',
   E'Náuseas, icterícia/escleras amareladas, erupção cutânea, cefaleias e dor abdominal (as mais frequentes, ≥2%).\nVómitos, insónia, sintomas neurológicos periféricos, tonturas, mialgia, diarreia, depressão e febre.\nErupção cutânea grave (raramente SJS/NET) — procurar ajuda se alastrar ou com bolhas.\nAlterações cardíacas (prolongamento do PR) — palpitações ou desmaios.\nLitíase renal ou biliar.',
   E'Nausea, jaundice/yellow sclera, rash, headache and abdominal pain (most common, ≥2%).\nVomiting, insomnia, peripheral neurological symptoms, dizziness, myalgia, diarrhoea, depression and fever.\nSevere skin rash (rarely SJS/TEN) — seek help if it spreads or blisters.\nCardiac changes (PR prolongation) — palpitations or fainting.\nKidney or gall stones.',
   E'Tomar com alimentos (aumenta a absorção e reduz a variabilidade).\nA icterícia benigna (bilirrubina indireta) é frequente — não é lesão hepática, mas comunicar ao médico.\nUsar contraceção adequada — este medicamento pode interagir com contracetivos hormonais (avaliar alternativa).\nVigiar sintomas cardíacos (PR) em doentes com bloqueio de condução preexistente.\nNão tomar com omeprazol ou outros inibidores da bomba de protões sem indicação (reduzem a exposição).\nInformar o médico sobre toda a medicação — muitas interações com inibidores/indutores do CYP3A4.',
   E'Take with food (increases absorption and reduces variability).\nBenign jaundice (indirect bilirubin) is common — it is not liver injury, but tell your doctor.\nUse adequate contraception — this medicine can interact with hormonal contraceptives (consider alternatives).\nWatch for cardiac symptoms (PR) in patients with pre-existing conduction block.\nDo not take with omeprazole or other proton pump inhibitors without advice (they reduce exposure).\nTell your doctor about all medication — many interactions with CYP3A4 inhibitors/inducers.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Atazanavir (REYATAZ): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=165cff62-b284-4a27-a65d-9ec8a5bfcdd8',
   'DailyMed/FDA (NIH/NLM) — approved Atazanavir (REYATAZ) label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=165cff62-b284-4a27-a65d-9ec8a5bfcdd8'),

  ('azatioprina',
   'A azatioprina é um medicamento que modera o sistema imunitário (imunossupressor). É usada para prevenir a rejeição de órgãos transplantados e para tratar doenças autoimunes, como artrite reumatoide, lúpus ou doença inflamatória intestinal. O efeito demora semanas a meses a aparecer e exige vigilância regular de análises.',
   'Azathioprine is a medicine that calms the immune system (immunosuppressant). It is used to prevent rejection of transplanted organs and to treat autoimmune diseases such as rheumatoid arthritis, lupus or inflammatory bowel disease. The effect takes weeks to months to appear and requires regular blood monitoring.',
   'Antimetabólito imunossupressor (pró-fármaco da 6-mercaptopurina) que inibe a síntese de purinas e a proliferação de linfócitos. Adjuvante na prevenção da rejeição de transplante renal e no tratamento da artrite reumatoide ativa e de várias doenças autoimunes (uso off-label frequente: DII, lúpus, dermatomiosite). Metabolizado pela TPMT e NUDT15 — défice enzimático aumenta muito o risco de mielossupressão grave; a inibição da xantina-oxidase pelo alopurinol/febuxostate exige redução de dose para ~25%.',
   'Immunosuppressive antimetabolite (prodrug of 6-mercaptopurine) that inhibits purine synthesis and lymphocyte proliferation. Adjunct in the prevention of renal transplant rejection and in the treatment of active rheumatoid arthritis and various autoimmune diseases (frequent off-label use: IBD, lupus, dermatomyositis). Metabolised by TPMT and NUDT15 — enzyme deficiency greatly increases the risk of severe myelosuppression; xanthine oxidase inhibition by allopurinol/febuxostat requires dose reduction to ~25%.',
   E'Prevenção da rejeição em transplante renal (adjuvante).\nTratamento da artrite reumatoide ativa, para reduzir os sinais e sintomas.\n(Fora de indicação formal, mas uso estabelecido) doença inflamatória intestinal, lúpus eritematoso sistémico e outras doenças autoimunes.',
   E'Prevention of rejection in renal transplantation (adjunct).\nManagement of active rheumatoid arthritis to reduce signs and symptoms.\n(Off-label but established use) inflammatory bowel disease, systemic lupus erythematosus and other autoimmune diseases.',
   E'Mielossupressão — infeções, febre, cansaço, nódoas negras ou hemorragias invulgares: vigiar hemograma.\nNáuseas e vómitos (geralmente nas primeiras semanas).\nRisco aumentado de linfoma e outros tumores malignos, sobretudo da pele — limitar a exposição solar.\nLesão hepática e pancreatite.\nReações de hipersensibilidade (raras): febre, artralgias, erupção cutânea.',
   E'Myelosuppression — infections, fever, fatigue, unusual bruising or bleeding: monitor blood counts.\nNausea and vomiting (usually in the first weeks).\nIncreased risk of lymphoma and other malignancies, especially of the skin — limit sun exposure.\nLiver injury and pancreatitis.\nHypersensitivity reactions (rare): fever, arthralgia, rash.',
   E'Não usar durante a gravidez no tratamento da artrite reumatoide; usar contraceção eficaz (risco fetal).\nAntes de iniciar, considerar a determinação da atividade de TPMT/NUDT15.\nVigiar hemograma e provas hepáticas regularmente (mais frequente no início).\nCom alopurinol ou febuxostate: reduzir a dose de azatioprina para ~25% (risco de mielossupressão fatal).\nEvitar vacinas vivas durante o tratamento.\nComunicar febre, infeções ou hemorragias ao médico imediatamente.',
   E'Do not use during pregnancy for rheumatoid arthritis; use effective contraception (fetal risk).\nBefore starting, consider measurement of TPMT/NUDT15 activity.\nMonitor blood counts and liver tests regularly (more frequently early on).\nWith allopurinol or febuxostat: reduce azathioprine dose to ~25% (risk of fatal myelosuppression).\nAvoid live vaccines during treatment.\nReport fever, infections or bleeding to your doctor immediately.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Azatioprina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5116b22b-1460-5535-e063-6394a90acbe5',
   'DailyMed/FDA (NIH/NLM) — approved Azathioprine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5116b22b-1460-5535-e063-6394a90acbe5'),

  ('bedaquilina',
   'A bedaquilina é um antibiótico usado no tratamento da tuberculose resistente (multirresistente), sempre em associação com outros medicamentos. É tomada por via oral com alimentos. Por ser um medicamento especializado, é usada sob supervisão de equipas experientes no tratamento da tuberculose.',
   'Bedaquiline is an antibiotic used to treat resistant (multidrug-resistant) tuberculosis, always in combination with other medicines. It is taken orally with food. As a specialist medicine, it is used under the supervision of teams experienced in tuberculosis treatment.',
   'Antimicobacteriano diarilquinolínico que inibe a ATP-sintase micobacteriana (subunidade c), com atividade específica contra o Mycobacterium tuberculosis, incluindo estirpes multirresistentes. Indicado como parte de regimes combinados no tratamento da tuberculose pulmonar (adultos e crianças ≥2 anos) quando não há alternativa razoável por resistência. Semivida terminal muito longa (~5,5 meses); risco de prolongamento do QTc — monitorização eletrocardiográfica durante o tratamento.',
   'Diarylquinoline antimycobacterial that inhibits mycobacterial ATP synthase (c subunit), with specific activity against Mycobacterium tuberculosis, including multidrug-resistant strains. Indicated as part of combination regimens for pulmonary tuberculosis (adults and children ≥2 years) when no reasonable alternative exists due to resistance. Very long terminal half-life (~5.5 months); risk of QTc prolongation — electrocardiographic monitoring during treatment.',
   E'Tratamento da tuberculose pulmonar causada por estirpes de Mycobacterium tuberculosis multirresistentes (MDR-TB), em adultos e crianças ≥2 anos com peso ≥8 kg, como parte de uma terapêutica combinada.',
   E'Treatment of pulmonary tuberculosis caused by multidrug-resistant strains of Mycobacterium tuberculosis (MDR-TB) in adults and paediatric patients ≥2 years weighing at least 8 kg, as part of a combination therapy.',
   E'Náuseas, artralgias, cefaleias, hemoptise e dor torácica (≥10%).\nProlongamento do QTc e arritmias — palpitações, desmaios: procurar ajuda.\nElevação das transaminases e hepatotoxicidade (vigiar provas hepáticas).\nMortalidade aumentada em ensaio na TB não resistente (uso reservado à TB resistente).\nAnemia, leucopenia.',
   E'Nausea, arthralgia, headache, haemoptysis and chest pain (≥10%).\nQTc prolongation and arrhythmias — palpitations, fainting: seek help.\nElevated transaminases and hepatotoxicity (monitor liver tests).\nIncreased mortality in a trial in non-resistant TB (use reserved for resistant TB).\nAnaemia, leukopenia.',
   E'Tomar com alimentos (aumenta a absorção 2 vezes).\nTratamento sempre em associação com outros antituberculosos — nunca em monoterapia.\nVigiar ECG (QTc) e eletrólitos (K, Mg, Ca) durante o tratamento.\nEvitar fármacos que prolongam o QTc ou inibidores/indutores do CYP3A4 quando possível.\nVigiar provas hepáticas; comunicar icterícia, urina escura ou cansaço intenso.\nEvitar a gravidez (risco fetal desconhecido) — usar contraceção eficaz.',
   E'Take with food (increases absorption 2-fold).\nAlways in combination with other antituberculosis drugs — never as monotherapy.\nMonitor ECG (QTc) and electrolytes (K, Mg, Ca) during treatment.\nAvoid QTc-prolonging drugs or CYP3A4 inhibitors/inducers when possible.\nMonitor liver tests; report jaundice, dark urine or severe fatigue.\nAvoid pregnancy (unknown fetal risk) — use effective contraception.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Bedaquilina (SIRTURO): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1534c9ae-4948-4cf4-9f66-222a99db6d0e',
   'DailyMed/FDA (NIH/NLM) — approved Bedaquiline (SIRTURO) label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1534c9ae-4948-4cf4-9f66-222a99db6d0e'),

  ('calcitriol',
   'O calcitriol é a forma ativa da vitamina D. É usado para tratar a falta de cálcio e as alterações ósseas em pessoas com doença renal (incluindo em diálise) e em pessoas com hipoparatiroidismo. A dose é ajustada com análises regulares de cálcio.',
   'Calcitriol is the active form of vitamin D. It is used to treat calcium deficiency and bone changes in people with kidney disease (including dialysis) and in people with hypoparathyroidism. The dose is adjusted with regular calcium tests.',
   'Vitamina D ativa (1,25-di-hidroxicolecalciferol) que promove a absorção intestinal de cálcio, a mobilização óssea e a reabsorção renal, controlando a hiperparatiroidia secundária e a doença óssea metabólica na doença renal crónica e a hipocalcemia no hipoparatiroidismo. Ação rápida e curta em comparação com a vitamina D; exige monitorização estreita do cálcio sérico (hipercalcemia é o risco principal).',
   'Active vitamin D (1,25-dihydroxycholecalciferol) that promotes intestinal calcium absorption, bone mobilisation and renal reabsorption, controlling secondary hyperparathyroidism and metabolic bone disease in chronic kidney disease and hypocalcaemia in hypoparathyroidism. Rapid and short action compared with vitamin D; requires close monitoring of serum calcium (hypercalcaemia is the main risk).',
   E'Gestão da hiperparatiroidia secundária e da doença óssea metabólica em doentes com doença renal crónica moderada a grave (TFG 15–55 mL/min) ainda não em diálise.\nGestão da hipocalcemia e da doença óssea metabólica em doentes em diálise renal crónica.\nGestão da hipocalcemia e suas manifestações clínicas no hipoparatiroidismo pós-cirúrgico, idiopático e pseudo-hipoparatiroidismo.',
   E'Management of secondary hyperparathyroidism and resultant metabolic bone disease in patients with moderate to severe chronic renal failure (CrCl 15 to 55 mL/min) not yet on dialysis.\nManagement of hypocalcaemia and resultant metabolic bone disease in patients undergoing chronic renal dialysis.\nManagement of hypocalcaemia and its clinical manifestations in postsurgical, idiopathic and pseudohypoparathyroidism.',
   E'Hipercalcemia (o risco principal) — náuseas, vómitos, obstipação, sede, fraqueza, confusão: procurar ajuda.\nHipercalciúria e cálculos renais.\nReações de hipersensibilidade (raras).\nA sobredosagem de vitamina D é perigosa — pode exigir tratamento urgente.',
   E'Hypercalcaemia (the main risk) — nausea, vomiting, constipation, thirst, weakness, confusion: seek help.\nHypercalciuria and kidney stones.\nHypersensitivity reactions (rare).\nVitamin D overdosage is dangerous — may require urgent treatment.',
   E'Não usar em caso de hipercalcemia ou evidência de toxicidade por vitamina D.\nMonitorizar cálcio sérico (e fósforo) com frequência no início e sempre que se ajusta a dose.\nGarantir aporte adequado de cálcio (≥600 mg/dia), mas evitar excesso simultâneo de cálcio e vitamina D.\nVigiar sinais de hipercalcemia (sede, obstipação, fraqueza, confusão).\nCuidado com outros suplementos de vitamina D ou medicamentos contendo cálcio.',
   E'Do not use in hypercalcaemia or evidence of vitamin D toxicity.\nMonitor serum calcium (and phosphate) frequently at the start and whenever the dose is adjusted.\nEnsure adequate calcium intake (≥600 mg/day), but avoid simultaneous excess of calcium and vitamin D.\nWatch for signs of hypercalcaemia (thirst, constipation, weakness, confusion).\nBe careful with other vitamin D supplements or calcium-containing medicines.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Calcitriol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8465337c-86ca-ea9d-e053-2991aa0ab167',
   'DailyMed/FDA (NIH/NLM) — approved Calcitriol label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8465337c-86ca-ea9d-e053-2991aa0ab167'),

  ('captopril',
   'O captopril é um medicamento para a tensão arterial alta e para a insuficiência cardíaca (inibidor da ECA). Toma-se por via oral, de preferência uma hora antes das refeições, porque os alimentos reduzem a sua absorção. Pode provocar tosse seca — um efeito comum desta classe de medicamentos.',
   'Captopril is a medicine for high blood pressure and heart failure (ACE inhibitor). It is taken orally, preferably one hour before meals, because food reduces its absorption. It can cause a dry cough — a common effect of this class of medicines.',
   'Inibidor da enzima de conversão da angiotensina (IECA) que reduz a formação de angiotensina II e a degradação de bradicinina, diminuindo a resistência vascular periférica e a pressão arterial, com aumento do fluxo renal. Usado na hipertensão, insuficiência cardíaca, após enfarte e na nefropatia diabética. Absorção reduzida 30–40% pelos alimentos (tomar 1 hora antes); eliminação renal com acumulação na insuficiência renal. Angioedema e tosse são efeitos de classe.',
   'Angiotensin-converting enzyme inhibitor (ACEI) that reduces angiotensin II formation and bradykinin degradation, lowering peripheral vascular resistance and blood pressure, with increased renal blood flow. Used in hypertension, heart failure, post-myocardial infarction and diabetic nephropathy. Absorption reduced 30–40% by food (take 1 hour before); renal elimination with accumulation in renal impairment. Angioedema and cough are class effects.',
   E'Tratamento da hipertensão arterial (isolado ou em associação).\nTratamento da insuficiência cardíaca (em associação com diuréticos e digitálicos).\nApós enfarte do miocárdio em doentes clinicamente estáveis (melhora a sobrevivência).\nNefropatia diabética (proteção renal).',
   E'Treatment of hypertension (alone or in combination).\nTreatment of heart failure (in combination with diuretics and digitalis).\nAfter myocardial infarction in clinically stable patients (improves survival).\nDiabetic nephropathy (renal protection).',
   E'Tosse seca persistente (efeito de classe — pode surgir semanas após o início).\nHipotensão, sobretudo no início ou em doentes com depleção de volume — tonturas, desmaios.\nHipercaliemia (risco maior com diuréticos poupadores de potássio ou IR).\nAngioedema (inchaço da face, lábios, língua ou garganta — urgência).\nAlteração do paladar, erupção cutânea, proteinúria (raros).',
   E'Persistent dry cough (class effect — may appear weeks after starting).\nHypotension, especially at the start or in volume-depleted patients — dizziness, fainting.\nHyperkalaemia (greater risk with potassium-sparing diuretics or renal impairment).\nAngioedema (swelling of the face, lips, tongue or throat — emergency).\nTaste disturbance, skin rash, proteinuria (rare).',
   E'Tomar 1 hora antes das refeições (os alimentos reduzem a absorção 30–40%).\nVigiar a pressão arterial e a função renal no início e nos ajustes de dose.\nEvitar suplementos de potássio e substitutos do sal com potássio sem indicação.\nProcurar ajuda imediata perante inchaço da face/língua ou dificuldade em respirar (angioedema).\nNão usar na gravidez (risco fetal) — informar o médico se engravidar.\nEvitar álcool (potencia a hipotensão).',
   E'Take 1 hour before meals (food reduces absorption 30–40%).\nMonitor blood pressure and renal function at the start and with dose adjustments.\nAvoid potassium supplements and potassium-based salt substitutes without advice.\nSeek immediate help for facial/tongue swelling or difficulty breathing (angioedema).\nDo not use in pregnancy (fetal risk) — tell your doctor if you become pregnant.\nAvoid alcohol (enhances hypotension).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Captopril: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=563737c5-4d63-4957-8022-e3bc3112dfac',
   'DailyMed/FDA (NIH/NLM) — approved Captopril label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=563737c5-4d63-4957-8022-e3bc3112dfac'),

  ('colchicina',
   'A colchicina é um medicamento usado para tratar e prevenir as crises de gota e para tratar a febre familiar do Mediterrâneo. É eficaz, mas tem uma janela terapêutica estreita: a dose excessiva é tóxica. Deve ser usada com muita cautela em pessoas com doença renal ou hepática.',
   'Colchicine is a medicine used to treat and prevent gout flares and to treat familial Mediterranean fever. It is effective, but has a narrow therapeutic window: excessive doses are toxic. It must be used very cautiously in people with kidney or liver disease.',
   'Alcaloide anti-inflamatório que se liga à tubulina, inibindo a mitose, a quimiotaxia e a adesão dos neutrófilos, bloqueando a resposta inflamatória da crise de gota. Indicado na profilaxia e tratamento das crises agudas de gota e na febre familiar do Mediterrâneo. Substrato do CYP3A4 e da glicoproteína-P — inibidores potentes (claritromicina, cetoconazol, ciclosporina) aumentam muito a toxicidade; a dose deve ser reduzida na IR e na IH.',
   'Anti-inflammatory alkaloid that binds tubulin, inhibiting mitosis, neutrophil chemotaxis and adhesion, blocking the inflammatory response of the gout flare. Indicated for prophylaxis and treatment of acute gout flares and for familial Mediterranean fever. Substrate of CYP3A4 and P-glycoprotein — potent inhibitors (clarithromycin, ketoconazole, ciclosporin) greatly increase toxicity; dose must be reduced in renal and hepatic impairment.',
   E'Profilaxia e tratamento das crises agudas de gota.\nTratamento da febre familiar do Mediterrâneo (FFM) em adultos e crianças.',
   E'Prophylaxis and treatment of acute gout flares.\nTreatment of familial Mediterranean fever (FMF) in adults and children.',
   E'Diarreia (a mais frequente), náuseas, vómitos e dor abdominal.\nDor faringolaríngea.\nToxicidade (dose excessiva ou interação): diarreia grave, vómitos, dor abdominal, fraqueza muscular, formigueiros — parar e procurar ajuda urgente.\nMielossupressão, neuropatia e toxicidade muscular (raros, mas graves).',
   E'Diarrhoea (most common), nausea, vomiting and abdominal pain.\nPharyngolaryngeal pain.\nToxicity (excessive dose or interaction): severe diarrhoea, vomiting, abdominal pain, muscle weakness, tingling — stop and seek urgent help.\nMyelosuppression, neuropathy and myotoxicity (rare but serious).',
   E'Dose reduzida na insuficiência renal e hepática e nos idosos — nunca exceder a dose prescrita.\nEvitar associação com inibidores potentes do CYP3A4/P-gp (claritromicina, cetoconazol, ciclosporina, verapamil) — risco de toxicidade fatal; se inevitável, reduzir muito a dose.\nSuspender perante diarreia grave, vómitos ou fraqueza muscular.\nVigiar hemograma e função muscular nos tratamentos prolongados.',
   E'Reduce the dose in renal and hepatic impairment and in the elderly — never exceed the prescribed dose.\nAvoid combination with potent CYP3A4/P-gp inhibitors (clarithromycin, ketoconazole, ciclosporin, verapamil) — risk of fatal toxicity; if unavoidable, greatly reduce the dose.\nStop in the presence of severe diarrhoea, vomiting or muscle weakness.\nMonitor blood counts and muscle function in prolonged treatment.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Colchicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=72984aa2-6df9-4460-9926-399ffed30e36',
   'DailyMed/FDA (NIH/NLM) — approved Colchicine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=72984aa2-6df9-4460-9926-399ffed30e36'),

  ('dabigatrano',
   'O dabigatrano é um anticoagulante (dilui o sangue) usado para prevenir AVC em pessoas com fibrilhação auricular e para tratar e prevenir tromboses. As cápsulas não devem ser abertas nem mastigadas. Como todos os anticoagulantes, aumenta o risco de hemorragia.',
   'Dabigatran is an anticoagulant (blood thinner) used to prevent stroke in people with atrial fibrillation and to treat and prevent blood clots. The capsules must not be opened or chewed. Like all anticoagulants, it increases the risk of bleeding.',
   'Anticoagulante oral de ação direta, inibidor reversível da trombina (fator IIa). Indicado na prevenção de AVC e embolia sistémica na fibrilhação auricular não valvular, no tratamento e prevenção de TVP/EP e na profilaxia ortopédica. Pró-fármaco (etexilato) com absorção dependente do pH gástrico (cápsulas não devem ser abertas). Eliminação renal dominante (~80% da depuração total) — contraindicação na IR grave; substrato da glicoproteína-P.',
   'Direct-acting oral anticoagulant, reversible inhibitor of thrombin (factor IIa). Indicated for stroke and systemic embolism prevention in non-valvular atrial fibrillation, treatment and prevention of DVT/PE and orthopaedic prophylaxis. Prodrug (etexilate) with absorption dependent on gastric pH (capsules must not be opened). Predominant renal elimination (~80% of total clearance) — contraindicated in severe renal impairment; P-glycoprotein substrate.',
   E'Redução do risco de AVC e embolia sistémica em adultos com fibrilhação auricular não valvular.\nTratamento da TVP e da EP em adultos.\nPrevenção da recorrência de TVP e EP.\nProfilaxia da TVP após artroplastia eletiva da anca ou joelho.',
   E'Reduction of the risk of stroke and systemic embolism in adult patients with non-valvular atrial fibrillation.\nTreatment of DVT and PE in adults.\nPrevention of recurrent DVT and PE.\nProphylaxis of DVT following elective hip or knee replacement.',
   E'Hemorragia (a mais comum, >15% com efeitos gastrointestinais) — nariz, gengivas, nódoas negras, sangue na urina ou fezes.\nDispesia e sintomas gastrointestinais (dor abdominal, diarreia, náuseas).\nAnemia.\nProcurar ajuda urgente perante hemorragia anormal, vómitos com sangue ou fezes escuras.',
   E'Bleeding (most common, >15% with gastrointestinal effects) — nose, gums, bruises, blood in urine or stools.\nDyspepsia and gastrointestinal symptoms (abdominal pain, diarrhoea, nausea).\nAnaemia.\nSeek urgent help for abnormal bleeding, vomiting blood or dark stools.',
   E'Não abrir, mastigar ou partir as cápsulas (aumenta muito a absorção e o risco de hemorragia).\nNão usar na insuficiência renal grave; ajustar a dose na IR moderada.\nInformar sobre toda a medicação — evitar indutores/inibidores fortes da glicoproteína-P (ex.: rifampicina, cetoconazol, ciclosporina).\nAntes de cirurgias ou procedimentos invasivos, informar a equipa.\nSuspender perante hemorragia invulgar e procurar ajuda.',
   E'Do not open, chew or crush the capsules (greatly increases absorption and bleeding risk).\nDo not use in severe renal impairment; adjust the dose in moderate renal impairment.\nTell your doctor about all medication — avoid strong P-glycoprotein inducers/inhibitors (e.g. rifampicin, ketoconazole, ciclosporin).\nBefore surgery or invasive procedures, inform the team.\nStop and seek help for unusual bleeding.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Dabigatrano etexilato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3a8ec82a-c367-40dc-9302-e1896fcb05ea',
   'DailyMed/FDA (NIH/NLM) — approved Dabigatran etexilate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3a8ec82a-c367-40dc-9302-e1896fcb05ea'),

  ('efavirenz',
   'O efavirenz é um medicamento antirretroviral usado no tratamento da infeção por VIH, em associação com outros medicamentos. Nas primeiras semanas pode causar tonturas, pesadelos e dificuldade de concentração, que tendem a melhorar; tomar à noite ajuda a tolerar estes efeitos.',
   'Efavirenz is an antiretroviral medicine used to treat HIV infection, in combination with other medicines. In the first weeks it can cause dizziness, nightmares and difficulty concentrating, which tend to improve; taking it at night helps tolerate these effects.',
   'Inibidor não nucleósido da transcriptase reversa do VIH-1 (NNRTI), usado em associação no tratamento da infeção por VIH-1 em adultos e crianças ≥3 meses. Efeitos neuropsiquiátricos frequentes (tonturas, sonhos anómalos, alterações da concentração) que geralmente melhoram nas primeiras 2–4 semanas; erupção cutânea frequente (raramente SJS). Indutor do CYP3A4 e CYP2B6 (autoindução) — interações relevantes com muitos fármacos. Teratogenicidade em primatas — evitar na gravidez.',
   'Non-nucleoside reverse transcriptase inhibitor of HIV-1 (NNRTI), used in combination for the treatment of HIV-1 infection in adults and children ≥3 months. Frequent neuropsychiatric effects (dizziness, abnormal dreams, impaired concentration) that usually improve in the first 2–4 weeks; frequent rash (rarely SJS). Inducer of CYP3A4 and CYP2B6 (autoinduction) — relevant interactions with many drugs. Teratogenicity in primates — avoid in pregnancy.',
   E'Tratamento da infeção por VIH-1 em adultos e em doentes pediátricos com ≥3 meses e peso ≥3,5 kg, em associação com outros antirretrovirais.',
   E'Treatment of HIV-1 infection in adults and in paediatric patients aged at least 3 months weighing at least 3.5 kg, in combination with other antiretrovirals.',
   E'Dificuldade de concentração, sonhos anómalos, tonturas, náuseas, cefaleias, fadiga, insónia e vómitos (>5%, moderados a graves).\nErupção cutânea (frequente; raramente SJS/NET — parar se alastrar ou com bolhas).\nElevação das transaminases e hepatotoxicidade.\nHipercolesterolemia e aumento dos triglicéridos.\nSintomas psiquiátricos — depressão, ideação suicida (vigiar).',
   E'Impaired concentration, abnormal dreams, dizziness, nausea, headache, fatigue, insomnia and vomiting (>5%, moderate to severe).\nSkin rash (common; rarely SJS/TEN — stop if it spreads or blisters).\nElevated transaminases and hepatotoxicity.\nHypercholesterolaemia and raised triglycerides.\nPsychiatric symptoms — depression, suicidal ideation (monitor).',
   E'Tomar preferencialmente à noite, em jejum (reduz os efeitos neuropsiquiátricos).\nNão usar na gravidez (risco teratogénico) — teste de gravidez antes de iniciar e contraceção eficaz.\nVigiar sintomas psiquiátricos (depressão, alterações do humor).\nEvitar álcool e outras substâncias psicoativas.\nInformar o médico sobre toda a medicação — indutor enzimático, muitas interações (contracetivos hormonais, varfarina, antifúngicos).\nCuidado na condução nas primeiras semanas.',
   E'Take preferably at night, on an empty stomach (reduces neuropsychiatric effects).\nDo not use in pregnancy (teratogenic risk) — pregnancy test before starting and effective contraception.\nMonitor psychiatric symptoms (depression, mood changes).\nAvoid alcohol and other psychoactive substances.\nTell your doctor about all medication — enzyme inducer, many interactions (hormonal contraceptives, warfarin, antifungals).\nTake care when driving in the first weeks.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Efavirenz: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=92603fa5-7a2c-4bfb-9a70-aadb4fba952c',
   'DailyMed/FDA (NIH/NLM) — approved Efavirenz label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=92603fa5-7a2c-4bfb-9a70-aadb4fba952c'),

  ('enalapril',
   'O enalapril é um medicamento para a tensão arterial alta e para a insuficiência cardíaca (inibidor da ECA). Toma-se por via oral, com ou sem alimentos. Pode provocar tosse seca — um efeito comum desta classe de medicamentos.',
   'Enalapril is a medicine for high blood pressure and heart failure (ACE inhibitor). It is taken orally, with or without food. It can cause a dry cough — a common effect of this class of medicines.',
   'Inibidor da enzima de conversão da angiotensina (IECA); pró-fármaco hidrolisado a enalaprilato, o inibidor ativo. Usado na hipertensão, insuficiência cardíaca, disfunção ventricular esquerda assintomática e na prevenção de eventos cardiovasculares em doentes de risco. Absorção ~60%, não afetada pelos alimentos; eliminação renal. Efeitos de classe: tosse seca, hipercaliemia, angioedema, deterioração da função renal em estenose bilateral das artérias renais.',
   'Angiotensin-converting enzyme inhibitor (ACEI); prodrug hydrolysed to enalaprilat, the active inhibitor. Used in hypertension, heart failure, asymptomatic left ventricular dysfunction and prevention of cardiovascular events in at-risk patients. Absorption ~60%, not affected by food; renal elimination. Class effects: dry cough, hyperkalaemia, angioedema, renal deterioration in bilateral renal artery stenosis.',
   E'Tratamento da hipertensão arterial (isolado ou em associação).\nTratamento da insuficiência cardíaca sintomática (em associação com diuréticos e, quando indicado, digitálicos).\nPrevenção da insuficiência cardíaca sintomática em doentes com disfunção ventricular esquerda assintomática.\nPrevenção de eventos cardiovasculares (enfarte, AVC) em doentes de risco com evidência de doença cardiovascular.',
   E'Treatment of hypertension (alone or in combination).\nTreatment of symptomatic heart failure (in combination with diuretics and, when indicated, digitalis).\nPrevention of symptomatic heart failure in patients with asymptomatic left ventricular dysfunction.\nPrevention of cardiovascular events (myocardial infarction, stroke) in at-risk patients with evidence of cardiovascular disease.',
   E'Tosse seca persistente (efeito de classe — pode surgir semanas após o início).\nHipotensão, sobretudo no início ou com depleção de volume — tonturas, desmaios.\nHipercaliemia (risco maior com diuréticos poupadores de potássio, IR ou suplementos).\nAngioedema (inchaço da face, lábios, língua ou garganta — urgência).\nCefaleias, fadiga, náuseas, alteração do paladar.',
   E'Persistent dry cough (class effect — may appear weeks after starting).\nHypotension, especially at the start or with volume depletion — dizziness, fainting.\nHyperkalaemia (greater risk with potassium-sparing diuretics, renal impairment or supplements).\nAngioedema (swelling of the face, lips, tongue or throat — emergency).\nHeadache, fatigue, nausea, taste disturbance.',
   E'Vigiar a pressão arterial, função renal e potássio no início e nos ajustes de dose.\nEvitar suplementos de potássio e substitutos do sal com potássio sem indicação.\nProcurar ajuda imediata perante inchaço da face/língua ou dificuldade em respirar (angioedema).\nNão usar na gravidez (risco fetal) — informar o médico se engravidar.\nCautela na condução no início (hipotensão).\nTomar com ou sem alimentos, de preferência à mesma hora.',
   E'Monitor blood pressure, renal function and potassium at the start and with dose adjustments.\nAvoid potassium supplements and potassium-based salt substitutes without advice.\nSeek immediate help for facial/tongue swelling or difficulty breathing (angioedema).\nDo not use in pregnancy (fetal risk) — tell your doctor if you become pregnant.\nTake care when driving early in treatment (hypotension).\nTake with or without food, preferably at the same time.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Enalapril: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0c829189-fba2-48f8-a23f-d5471a0345f6',
   'DailyMed/FDA (NIH/NLM) — approved Enalapril label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0c829189-fba2-48f8-a23f-d5471a0345f6'),

  ('enoxaparina',
   'A enoxaparina é um anticoagulante (heparina de baixo peso molecular) administrado por injeção subcutânea, usado para prevenir e tratar coágulos sanguíneos (tromboses e embolias) e em situações de síndromes coronárias agudas. As injeções são geralmente feitas pelo próprio doente ou por um familiar, após treino.',
   'Enoxaparin is an anticoagulant (low molecular weight heparin) given by subcutaneous injection, used to prevent and treat blood clots (deep vein thrombosis and pulmonary embolism) and in acute coronary syndromes. The injections are usually given by the patient or a family member after training.',
   'Heparina de baixo peso molecular (HBPM) que potencia a antitrombina III, inibindo preferencialmente o fator Xa (e, em menor grau, o fator IIa). Indicada na profilaxia e tratamento da TVP/EP, no tratamento da angina instável/enfarte sem onda Q, no enfarte com elevação do ST (adjuvante) e na profilaxia em doentes médicos acamados. Administração subcutânea com biodisponibilidade ~100%; eliminação renal (ajustar na IR). Antídoto parcial: protamina. Risco de hemorragia e trombocitopenia induzida por heparina (vigiar plaquetas).',
   'Low molecular weight heparin (LMWH) that potentiates antithrombin III, inhibiting preferentially factor Xa (and, to a lesser extent, factor IIa). Indicated for prophylaxis and treatment of DVT/PE, treatment of unstable angina/non-Q-wave infarction, ST-elevation myocardial infarction (adjunct) and prophylaxis in bedridden medical patients. Subcutaneous administration with ~100% bioavailability; renal elimination (adjust in renal impairment). Partial antidote: protamine. Risk of bleeding and heparin-induced thrombocytopenia (monitor platelets).',
   E'Profilaxia da TVP (que pode levar a EP) em cirurgia abdominal, ortopédica e em doentes médicos acamados com risco tromboembólico.\nTratamento da TVP com ou sem EP (em associação com varfarina).\nTratamento da angina instável e do enfarte do miocárdio sem onda Q (com aspirina).\nAdjuvante no enfarte agudo com elevação do ST.\nPrevenção da coagulação no circuito de hemodiálise.',
   E'Prophylaxis of DVT (which may lead to PE) in abdominal and orthopaedic surgery and in bedridden medical patients at thromboembolic risk.\nTreatment of DVT with or without PE (in combination with warfarin).\nTreatment of unstable angina and non-Q-wave myocardial infarction (with aspirin).\nAdjunct in acute ST-elevation myocardial infarction.\nPrevention of clotting in the haemodialysis circuit.',
   E'Hemorragia (a mais comum, >1%) — nódoas negras, hemorragia de feridas, sangue na urina ou fezes.\nAnemia e trombocitopenia (vigiar plaquetas — suspeita de trombocitopenia induzida por heparina).\nElevação das transaminases (transitória).\nDor, equimose ou nódulo no local da injeção.\nRaramente: hematoma espinal com punção/epidural, reações alérgicas.',
   E'Bleeding (most common, >1%) — bruises, wound bleeding, blood in urine or stools.\nAnaemia and thrombocytopenia (monitor platelets — suspicion of heparin-induced thrombocytopenia).\nElevated transaminases (transient).\nPain, bruising or nodule at the injection site.\nRarely: spinal haematoma with puncture/epidural, allergic reactions.',
   E'Injetar por via subcutânea (nunca intramuscular), rodando os locais de injeção.\nNão usar na hemorragia ativa, trombocitopenia grave ou alergia à enoxaparina; usar com cautela na IR grave (reduzir dose).\nCom anestesia espinal/epidural ou punção lombar: respeitar os intervalos recomendados (risco de hematoma espinal).\nVigiar sinais de hemorragia e comunicar ao médico.\nNão administrar se o doente estiver sob outros anticoagulantes sem indicação.',
   E'Inject subcutaneously (never intramuscular), rotating injection sites.\nDo not use in active bleeding, severe thrombocytopenia or enoxaparin allergy; use with caution in severe renal impairment (reduce dose).\nWith spinal/epidural anaesthesia or lumbar puncture: respect the recommended intervals (risk of spinal haematoma).\nMonitor signs of bleeding and tell your doctor.\nDo not administer with other anticoagulants without advice.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Enoxaparina (LOVENOX): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5017a927-2a24-4f27-89f9-27c805bf7d59',
   'DailyMed/FDA (NIH/NLM) — approved Enoxaparin (LOVENOX) label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5017a927-2a24-4f27-89f9-27c805bf7d59'),

  ('estreptomicina',
   'A estreptomicina é um antibiótico (aminoglicosídeo) administrado por injeção intramuscular, usado principalmente no tratamento da tuberculose e de algumas infeções graves, sempre em associação com outros antibióticos. O principal risco é a toxicidade para o ouvido (audição e equilíbrio) e para os rins.',
   'Streptomycin is an antibiotic (aminoglycoside) given by intramuscular injection, used mainly to treat tuberculosis and some serious infections, always in combination with other antibiotics. The main risk is toxicity to the ear (hearing and balance) and kidneys.',
   'Antibiótico aminoglicosídeo bactericida que inibe a síntese proteica bacteriana (ligação à subunidade ribossomal 30S), com atividade contra micobactérias (incluindo M. tuberculosis) e vários gram-negativos. Usado na tuberculose (como quarto fármaco ou quando outros estão contraindicados) e em infeções não tuberculosas suscetíveis não tratáveis com agentes menos tóxicos (peste, tularemia, brucelose, endocardite estreptocócica em associação). Ototoxicidade vestibular e coclear e nefrotoxicidade são os efeitos limitantes; monitorizar audição, equilíbrio e função renal.',
   'Bactericidal aminoglycoside antibiotic that inhibits bacterial protein synthesis (binding to the 30S ribosomal subunit), active against mycobacteria (including M. tuberculosis) and several Gram-negatives. Used in tuberculosis (as the fourth drug or when others are contraindicated) and in susceptible non-tuberculous infections not amenable to less toxic agents (plague, tularemia, brucellosis, streptococcal endocarditis in combination). Vestibular and cochlear ototoxicity and nephrotoxicity are the dose-limiting effects; monitor hearing, balance and renal function.',
   E'Tratamento da tuberculose (como quarto fármaco em regime inicial, ou quando a isoniazida/rifampicina estão contraindicadas).\nInfeções não tuberculosas por bactérias suscetíveis não tratáveis com agentes menos tóxicos: peste (Yersinia pestis), tularemia, brucelose, cancroide, infeções urinárias por germes suscetíveis, endocardite estreptocócica (com penicilina).',
   E'Treatment of tuberculosis (as the fourth drug in the initial regimen, or when isoniazid/rifampicin are contraindicated).\nNon-tuberculous infections caused by susceptible bacteria not amenable to less toxic agents: plague (Yersinia pestis), tularemia, brucellosis, chancroid, urinary tract infections by susceptible organisms, streptococcal endocarditis (with penicillin).',
   E'Ototoxicidade vestibular (náuseas, vómitos, vertigens) — frequente.\nParestesias faciais, erupção cutânea, febre, urticária, angioedema e eosinofilia.\nOtotoxicidade coclear (surdez) — menos frequente, mas pode ser irreversível.\nNefrotoxicidade (azotemia), dermatite esfoliativa, anafilaxia (raros).\nDores no local da injeção.',
   E'Vestibular ototoxicity (nausea, vomiting, vertigo) — common.\nFacial paraesthesia, rash, fever, urticaria, angioedema and eosinophilia.\nCochlear ototoxicity (deafness) — less frequent but may be irreversible.\nNephrotoxicity (azotaemia), exfoliative dermatitis, anaphylaxis (rare).\nPain at the injection site.',
   E'Administração exclusivamente intramuscular (não usar por via oral).\nVigiar audição, equilíbrio e função renal (especialmente em idosos, IR preexistente ou tratamentos prolongados).\nEvitar associação com outros aminoglicosídeos ou diuréticos de ansa (toxicidade aditiva).\nUsar com cautela na gravidez (risco fetal).\nTratamento sempre em associação na tuberculose — nunca em monoterapia.',
   E'Intramuscular administration only (do not use orally).\nMonitor hearing, balance and renal function (especially in the elderly, pre-existing renal impairment or prolonged courses).\nAvoid combination with other aminoglycosides or loop diuretics (additive toxicity).\nUse with caution in pregnancy (fetal risk).\nAlways in combination in tuberculosis — never as monotherapy.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Estreptomicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=abd1f64e-4283-4370-aae8-3666316aa36e',
   'DailyMed/FDA (NIH/NLM) — approved Streptomycin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=abd1f64e-4283-4370-aae8-3666316aa36e'),

  ('fenobarbital',
   'O fenobarbital é um medicamento antiepilético e sedativo (barbitúrico) usado no controlo de crises convulsivas. É eficaz, mas pode causar habituação e dependência, e a suspensão deve ser sempre gradual. Interage com muitos medicamentos porque acelera a sua eliminação.',
   'Phenobarbital is an antiepileptic and sedative medicine (barbiturate) used to control seizures. It is effective, but can cause habituation and dependence, and stopping must always be gradual. It interacts with many medicines because it speeds up their elimination.',
   'Barbitúrico de ação longa com propriedades anticonvulsivantes, sedativas e hipnóticas; potencializa o GABA-A (prolonga a abertura do canal de cloro), reduzindo a excitabilidade neuronal. Indicado no tratamento de crises generalizadas e parciais e como sedativo. Indutor enzimático hepático potente (CYP450) — reduz os níveis de muitos fármacos (anticoagulantes, contracetivos, muitos antiepiléticos). Potencial de habituação e dependência; abstinência grave se suspensão abrupta.',
   'Long-acting barbiturate with anticonvulsant, sedative and hypnotic properties; potentiates GABA-A (prolongs chloride channel opening), reducing neuronal excitability. Indicated for the treatment of generalised and partial seizures and as a sedative. Potent hepatic enzyme inducer (CYP450) — lowers levels of many drugs (anticoagulants, contraceptives, many antiepileptics). Potential for habituation and dependence; severe withdrawal if stopped abruptly.',
   E'Sedativo (uso limitado).\nAnticonvulsivante — tratamento de crises generalizadas e parciais.',
   E'Sedative (limited use).\nAnticonvulsant — treatment of generalised and partial seizures.',
   E'Sonolência, sedação e fadiga (frequentes no início).\nTonturas, ataxia e alterações do equilíbrio.\nDependência física e psicológica com uso prolongado.\nReações paradoxais de excitação (sobretudo em crianças e idosos).\nDéfices cognitivos em crianças com uso prolongado.\nDepressão respiratória (na sobredosagem).',
   E'Drowsiness, sedation and fatigue (common at the start).\nDizziness, ataxia and balance problems.\nPhysical and psychological dependence with prolonged use.\nParadoxical excitement reactions (especially in children and the elderly).\nCognitive deficits in children with prolonged use.\nRespiratory depression (in overdose).',
   E'Suspender sempre gradualmente — a suspensão abrupta pode causar convulsões, delírio e morte.\nNão usar na porfíria, insuficiência hepática grave ou doença respiratória grave.\nEvitar álcool e outros depressores do SNC (efeito aditivo).\nUsar com cautela em doentes com depressão ou ideação suicida.\nInformar o médico sobre toda a medicação — indutor enzimático, muitas interações (varfarina, contracetivos, muitos antiepiléticos).\nEvitar na gravidez (risco fetal); vigiar recém-nascidos de mães tratadas.',
   E'Always stop gradually — abrupt withdrawal can cause seizures, delirium and death.\nDo not use in porphyria, severe liver impairment or severe respiratory disease.\nAvoid alcohol and other CNS depressants (additive effect).\nUse with caution in patients with depression or suicidal ideation.\nTell your doctor about all medication — enzyme inducer, many interactions (warfarin, contraceptives, many antiepileptics).\nAvoid in pregnancy (fetal risk); monitor newborns of treated mothers.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Fenobarbital: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fa09b4f2-edb0-4594-a2d2-b16f7b9686b4',
   'DailyMed/FDA (NIH/NLM) — approved Phenobarbital label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fa09b4f2-edb0-4594-a2d2-b16f7b9686b4'),

  ('levofloxacina',
   'A levofloxacina é um antibiótico (fluoroquinolona) usado para tratar infeções respiratórias, urinárias, da pele e outras infeções bacterianas. É eficaz, mas pode causar efeitos secundários graves e por vezes irreversíveis nos tendões, nervos e sistema nervoso central — deve ser usada apenas quando não há alternativa.',
   'Levofloxacin is an antibiotic (fluoroquinolone) used to treat respiratory, urinary, skin and other bacterial infections. It is effective, but can cause serious and sometimes irreversible side effects on tendons, nerves and the central nervous system — it should only be used when there is no alternative.',
   'Fluoroquinolona bactericida que inibe as topoisomerases II (ADN-girase) e IV bacterianas, bloqueando a replicação do ADN. Largo espetro (gram-negativos, incluindo Pseudomonas, e gram-positivos). Associada a efeitos adversos graves e potencialmente irreversíveis: tendinite/rotura de tendão, neuropatia periférica, efeitos no SNC, exacerbação de miastenia grave, prolongamento do QTc e disglicemia. Reservada para infeções sem alternativa razoável.',
   'Bactericidal fluoroquinolone that inhibits bacterial topoisomerases II (DNA gyrase) and IV, blocking DNA replication. Broad spectrum (Gram-negatives, including Pseudomonas, and Gram-positives). Associated with serious and potentially irreversible adverse effects: tendinitis/tendon rupture, peripheral neuropathy, CNS effects, exacerbation of myasthenia gravis, QTc prolongation and dysglycaemia. Reserved for infections without a reasonable alternative.',
   E'Pneumonia nosocomial e comunitária.\nInfeções urinárias complicadas, pielonefrite aguda e prostatite bacteriana crónica.\nSinusite bacteriana aguda, exacerbações agudas de bronquite crónica.\nInfeções da pele e tecidos moles.\nAntraz por inalação (profilaxia e tratamento, pós-exposição).',
   E'Nosocomial and community-acquired pneumonia.\nComplicated urinary tract infections, acute pyelonephritis and chronic bacterial prostatitis.\nAcute bacterial sinusitis, acute exacerbations of chronic bronchitis.\nSkin and soft tissue infections.\nInhalational anthrax (post-exposure prophylaxis and treatment).',
   E'Riscos graves e potencialmente irreversíveis: tendinite e rotura de tendão (parar ao primeiro sinal de dor/inflamação), neuropatia periférica, efeitos no SNC (tonturas, confusão, convulsões), exacerbação de miastenia grave.\nNáuseas, diarreia, cefaleias e insónia.\nProlongamento do QTc e arritmias.\nAlterações da glicemia (hipo ou hiperglicemia).\nFotossensibilidade (evitar exposição solar).\nColite por Clostridioides difficile.',
   E'Serious and potentially irreversible risks: tendinitis and tendon rupture (stop at the first sign of pain/inflammation), peripheral neuropathy, CNS effects (dizziness, confusion, seizures), exacerbation of myasthenia gravis.\nNausea, diarrhoea, headache and insomnia.\nQTc prolongation and arrhythmias.\nBlood glucose changes (hypo or hyperglycaemia).\nPhotosensitivity (avoid sun exposure).\nClostridioides difficile colitis.',
   E'Parar imediatamente ao primeiro sinal de dor, inflamação ou rotura de tendão, formigueiros ou alterações neurológicas.\nEvitar em doentes com antecedentes de tendinopatia por quinolonas, miastenia grave, epilepsia não controlada ou QT longo.\nUsar com cautela em idosos, na IR e em doentes com diabetes (vigiar glicemia).\nEvitar antiácidos, ferro, zinco ou cálcio em simultâneo (reduzem a absorção — separar 2 horas).\nBeber bastante líquido (prevenir cristalúria).\nNão usar na gravidez e em crianças/adolescentes em crescimento, salvo indicação específica.',
   E'Stop immediately at the first sign of tendon pain, inflammation or rupture, tingling or neurological changes.\nAvoid in patients with a history of quinolone tendinopathy, myasthenia gravis, uncontrolled epilepsy or long QT.\nUse with caution in the elderly, in renal impairment and in patients with diabetes (monitor glucose).\nAvoid antacids, iron, zinc or calcium at the same time (reduce absorption — separate by 2 hours).\nDrink plenty of fluids (prevent crystalluria).\nDo not use in pregnancy and in growing children/adolescents unless specifically indicated.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Levofloxacina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=857f256c-88ac-4f73-9815-c2724edf2f1e',
   'DailyMed/FDA (NIH/NLM) — approved Levofloxacin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=857f256c-88ac-4f73-9815-c2724edf2f1e'),

  ('linezolida',
   'A linezolida é um antibiótico usado no tratamento de infeções graves, incluindo as causadas por bactérias resistentes (como o Staphylococcus aureus resistente à meticilina, MRSA). Toma-se por via oral ou intravenosa. É um inibidor da MAO, pelo que tem restrições alimentares e de medicação importantes.',
   'Linezolid is an antibiotic used to treat serious infections, including those caused by resistant bacteria (such as methicillin-resistant Staphylococcus aureus, MRSA). It is taken orally or intravenously. It is an MAO inhibitor, so it has important food and medication restrictions.',
   'Oxazolidinona bacteriostática que inibe a síntese proteica bacteriana (ligação à subunidade ribossomal 50S), com atividade contra gram-positivos, incluindo MRSA e enterococos resistentes à vancomicina (VRE). Inibidor reversível da MAO — risco de síndrome serotoninérgica com ISRS/ISRN e de crises hipertensivas com simpaticomiméticos. Vigiar mielossupressão (trombocitopenia) e neuropatia ótica/periférica nos tratamentos prolongados (>28 dias).',
   'Bacteriostatic oxazolidinone that inhibits bacterial protein synthesis (binding to the 50S ribosomal subunit), active against Gram-positives, including MRSA and vancomycin-resistant enterococci (VRE). Reversible MAO inhibitor — risk of serotonin syndrome with SSRIs/SNRIs and of hypertensive crises with sympathomimetics. Monitor myelosuppression (thrombocytopenia) and optic/peripheral neuropathy in prolonged treatment (>28 days).',
   E'Pneumonia nosocomial e comunitária (S. aureus suscetível e resistente à meticilina, Streptococcus pneumoniae).\nInfeções complicadas da pele e tecidos moles (incluindo MRSA e VRE).\nInfeções por enterococos resistentes à vancomicina (VRE), incluindo bacteriemia.\n(Outras infeções por gram-positivos resistentes, sob orientação de especialista.)',
   E'Nosocomial and community-acquired pneumonia (methicillin-susceptible and -resistant S. aureus, Streptococcus pneumoniae).\nComplicated skin and soft tissue infections (including MRSA and VRE).\nVancomycin-resistant Enterococcus (VRE) infections, including bacteraemia.\n(Other resistant Gram-positive infections, under specialist guidance.)',
   E'Diarreia, vómitos, cefaleias, náuseas e anemia (>5%).\nTrombocitopenia e outras citopenias (vigiar hemograma, sobretudo >2 semanas).\nNeuropatia periférica e ótica com uso prolongado (formigueiros, alterações visuais).\nSíndrome serotoninérgica se associado a ISRS/ISRN (agitação, febre, tremores — urgência).\nCandidíase e colite por Clostridioides difficile.',
   E'Diarrhoea, vomiting, headache, nausea and anaemia (>5%).\nThrombocytopenia and other cytopenias (monitor blood counts, especially beyond 2 weeks).\nPeripheral and optic neuropathy with prolonged use (tingling, visual changes).\nSerotonin syndrome if combined with SSRIs/SNRIs (agitation, fever, tremor — emergency).\nCandidiasis and Clostridioides difficile colitis.',
   E'Não associar a ISRS/ISRN, antidepressivos tricíclicos, tramadol, petidina ou simpaticomiméticos (síndrome serotoninérgica / crise hipertensiva).\nEvitar alimentos ricos em tiramina (queijos curados, cerveja, vinho) durante o tratamento.\nVigiar hemograma semanalmente em tratamentos >2 semanas.\nComunicar formigueiros, fraqueza ou alterações visuais (neuropatia).\nNão usar em doentes com hipertensão não controlada sem vigilância da tensão arterial.',
   E'Do not combine with SSRIs/SNRIs, tricyclic antidepressants, tramadol, pethidine or sympathomimetics (serotonin syndrome / hypertensive crisis).\nAvoid tyramine-rich foods (aged cheeses, beer, wine) during treatment.\nMonitor blood counts weekly in treatment beyond 2 weeks.\nReport tingling, weakness or visual changes (neuropathy).\nDo not use in uncontrolled hypertension without blood pressure monitoring.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Linezolida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=90dd8c13-c428-4472-91e5-5b1fcdc4fce3',
   'DailyMed/FDA (NIH/NLM) — approved Linezolid label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=90dd8c13-c428-4472-91e5-5b1fcdc4fce3'),

  ('metotrexato',
   'O metotrexato é um medicamento usado em doses baixas e semanais para tratar doenças inflamatórias (como artrite reumatoide e psoríase) e em doses mais altas no tratamento de alguns cancros. Em doses baixas toma-se uma vez por semana — confundir com a toma diária é um erro grave e perigoso.',
   'Methotrexate is a medicine used in low weekly doses to treat inflammatory diseases (such as rheumatoid arthritis and psoriasis) and in higher doses to treat some cancers. In low doses it is taken once a week — confusing this with a daily dose is a serious and dangerous mistake.',
   'Antagonista do folato que inibe a di-hidrofolato redutase (e, em baixas doses, a síntese de adenosina), com efeitos antiproliferativo e imunomodulador. Usado em baixas doses semanais na artrite reumatoide, psoríase e outras doenças inflamatórias, e em doses altas (com leucovorina) em neoplasias (LLA, linfomas, coriocarcinoma). Teratogénico e mielotóxico — a toma semanal em doenças não neoplásicas é crítica; interações com AINE, trimetoprim e probenecide aumentam a toxicidade.',
   'Folate antagonist that inhibits dihydrofolate reductase (and, at low doses, adenosine synthesis), with antiproliferative and immunomodulatory effects. Used in low weekly doses in rheumatoid arthritis, psoriasis and other inflammatory diseases, and in high doses (with leucovorin) in malignancies (ALL, lymphomas, choriocarcinoma). Teratogenic and myelotoxic — the weekly dosing in non-neoplastic diseases is critical; interactions with NSAIDs, trimethoprim and probenecid increase toxicity.',
   E'Doenças neoplásicas: tratamento da leucemia linfoblástica aguda (LLA, em regime combinado), micose fungóide, linfomas não Hodgkin e coriocarcinoma.\nDoenças não neoplásicas (doses baixas semanais): artrite reumatoide ativa grave, psoríase grave resistente (incluindo artrite psoriática).',
   E'Neoplastic diseases: treatment of acute lymphoblastic leukaemia (ALL, in combination regimens), mycosis fungoides, non-Hodgkin lymphomas and choriocarcinoma.\nNon-neoplastic diseases (low weekly doses): severe active rheumatoid arthritis, severe recalcitrant psoriasis (including psoriatic arthritis).',
   E'Mielossupressão — infeções, febre, cansaço, nódoas negras ou hemorragias (vigiar hemograma).\nHepatotoxicidade (elevação das transaminases, fibrose) — vigiar provas hepáticas.\nUlceração oral, náuseas e diarreia.\nPneumonite/toxidade pulmonar (tosse seca, falta de ar).\nNefrotoxicidade (doses altas).\nToxicidade neurológica (doses altas, intratecal).',
   E'Myelosuppression — infections, fever, fatigue, unusual bruising or bleeding (monitor blood counts).\nHepatotoxicity (elevated transaminases, fibrosis) — monitor liver tests.\nOral ulceration, nausea and diarrhoea.\nPneumonitis/pulmonary toxicity (dry cough, shortness of breath).\nNephrotoxicity (high doses).\nNeurological toxicity (high doses, intrathecal).',
   E'Tomar uma vez por semana (doenças não neoplásicas) — nunca diariamente; confusão de dose é um erro grave.\nNão usar na gravidez (teratogénico — contraceção eficaz durante e após o tratamento).\nVigiar hemograma, transaminases e creatinina regularmente.\nEvitar AINE em doses altas, trimetoprim/sulfametoxazol e probenecide (aumentam a toxicidade).\nÁcido fólico diário (exceto no dia da toma) reduz efeitos adversos sem perder eficácia.\nEvitar álcool (risco hepático).\nComunicar tosse seca ou falta de ar (possível pneumonite).',
   E'Take once a week (non-neoplastic diseases) — never daily; dose confusion is a serious error.\nDo not use in pregnancy (teratogenic — effective contraception during and after treatment).\nMonitor blood counts, transaminases and creatinine regularly.\nAvoid high-dose NSAIDs, trimethoprim/sulfamethoxazole and probenecid (increase toxicity).\nDaily folic acid (except on the dosing day) reduces adverse effects without losing efficacy.\nAvoid alcohol (liver risk).\nReport dry cough or shortness of breath (possible pneumonitis).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Metotrexato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=04a95db9-a124-4b97-bd71-1c37a6b3b0c8',
   'DailyMed/FDA (NIH/NLM) — approved Methotrexate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=04a95db9-a124-4b97-bd71-1c37a6b3b0c8'),

  ('pseudoefedrina',
   'A pseudoefedrina é um descongestionante nasal usado para aliviar temporariamente a congestão nasal e dos seios perinasais em constipações e alergias. Está disponível sem receita médica, mas deve ser usada com cuidado em pessoas com tensão alta, doenças cardíacas ou da tiroide.',
   'Pseudoephedrine is a nasal decongestant used to temporarily relieve nasal and sinus congestion in colds and allergies. It is available without prescription, but should be used with care in people with high blood pressure, heart or thyroid disease.',
   'Simpaticomimético (amina) com ação agonista alfa-1 adrenérgica predominante, que contrai os vasos da mucosa nasal e reduz a congestão e o edema. Descongestionante oral de eficácia estabelecida na congestão nasal da constipação e da rinite alérgica. Isómero com menos efeitos centrais que a efedrina; pode aumentar a pressão arterial e a frequência cardíaca. Excreção renal predominantemente inalterada (43–96%), dependente do pH urinário.',
   'Sympathomimetic (amine) with predominant alpha-1 adrenergic agonist action, constricting the nasal mucosal vessels and reducing congestion and oedema. Oral decongestant with established efficacy in nasal congestion of the common cold and allergic rhinitis. Isomer with fewer central effects than ephedrine; may raise blood pressure and heart rate. Predominantly renal excretion unchanged (43–96%), dependent on urinary pH.',
   E'Alívio temporário da congestão nasal devida à constipação comum, febre dos fenos ou outras alergias respiratórias superiores.\nAlívio temporário da congestão e pressão dos seios perinasais.',
   E'Temporarily relieves nasal congestion due to the common cold, hay fever or other upper respiratory allergies.\nTemporarily relieves sinus congestion and pressure.',
   E'Nervosismo, tonturas, insónia e tremores (mais frequentes).\nAumento da pressão arterial e da frequência cardíaca — palpitações.\nBoca seca, dificuldade em urinar (hipertrofia prostática).\nRaramente: reações alérgicas, arritmias.',
   E'Nervousness, dizziness, insomnia and tremor (most common).\nIncreased blood pressure and heart rate — palpitations.\nDry mouth, difficulty urinating (prostatic hypertrophy).\nRarely: allergic reactions, arrhythmias.',
   E'Não usar com inibidores da MAO (ou nas 2 semanas após parar) — crise hipertensiva.\nPerguntar ao médico antes de usar em caso de doença cardíaca, tensão alta, doença da tiroide, diabetes ou dificuldade em urinar por próstata.\nNão exceder a dose recomendada nem usar durante mais de 7 dias sem avaliação.\nEvitar à noite (insónia).\nNão usar em crianças <12 anos.',
   E'Do not use with MAO inhibitors (or within 2 weeks of stopping) — hypertensive crisis.\nAsk a doctor before use with heart disease, high blood pressure, thyroid disease, diabetes or difficulty urinating due to prostate problems.\nDo not exceed the recommended dose or use for more than 7 days without assessment.\nAvoid at night (insomnia).\nDo not use in children under 12 years.',
   'DailyMed/FDA (NIH/NLM) — rótulo OTC Pseudoefedrina (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8c4c786c-2b0f-4a23-a87d-effbcfe0c857',
   'DailyMed/FDA (NIH/NLM) — OTC Pseudoephedrine label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8c4c786c-2b0f-4a23-a87d-effbcfe0c857'),

  ('rifabutina',
   'A rifabutina é um antibiótico usado na prevenção e tratamento de infeções por micobactérias, incluindo a prevenção da infeção por Mycobacterium avium complex em pessoas com VIH avançado. Tal como a rifampicina, acelera a eliminação de muitos outros medicamentos.',
   'Rifabutin is an antibiotic used to prevent and treat mycobacterial infections, including prevention of Mycobacterium avium complex infection in people with advanced HIV. Like rifampicin, it speeds up the elimination of many other medicines.',
   'Antibiótico rifamicina (derivado da rifamicina-S), com atividade contra micobactérias atípicas (Mycobacterium avium complex), M. tuberculosis e alguns gram-positivos/negativos. Indutor mais fraco do CYP3A4 do que a rifampicina — frequentemente escolhido quando se pretende evitar as interações da rifampicina em doentes com VIH em terapêutica antirretroviral. Indutor da sua própria metabolização; associado a uveíte (dose-dependente), neutropenia e coloração alaranjada de fluidos.',
   'Rifamycin antibiotic (rifamycin-S derivative), active against atypical mycobacteria (Mycobacterium avium complex), M. tuberculosis and some Gram-positives/negatives. Weaker CYP3A4 inducer than rifampicin — often chosen when avoiding rifampicin interactions in HIV patients on antiretroviral therapy. Induces its own metabolism; associated with uveitis (dose-dependent), neutropenia and orange discolouration of body fluids.',
   E'Prevenção da infeção disseminada por Mycobacterium avium complex (MAC) em doentes com VIH avançado (contagem de CD4 muito baixa).\nTratamento de infeções por micobactérias atípicas (em associação).\n(Em associação) tratamento da tuberculose, quando a rifampicina não é adequada.',
   E'Prevention of disseminated Mycobacterium avium complex (MAC) infection in patients with advanced HIV (very low CD4 count).\nTreatment of atypical mycobacterial infections (in combination).\n(In combination) treatment of tuberculosis when rifampicin is not suitable.',
   E'Coloração alaranjada/vermelha da urina, suor, lágrimas e pele (esperada e inofensiva).\nNáuseas, vómitos, diarreia e dor abdominal.\nNeutropenia e outras citopenias (vigiar hemograma).\nUveíte (olhos vermelhos, dor ocular, visão turva — procurar ajuda).\nErupção cutânea, febre e elevação das transaminases.\nSintomas tipo gripe (com uso intermitente).',
   E'Orange/red discolouration of urine, sweat, tears and skin (expected and harmless).\nNausea, vomiting, diarrhoea and abdominal pain.\nNeutropenia and other cytopenias (monitor blood counts).\nUveitis (red eyes, eye pain, blurred vision — seek help).\nSkin rash, fever and elevated transaminases.\nFlu-like symptoms (with intermittent use).',
   E'Tomar sempre em associação com outros antimicobacterianos — nunca em monoterapia.\nPode reduzir o efeito de muitos medicamentos (contracetivos, varfarina, muitos antirretrovirais) — rever toda a medicação.\nVigiar hemograma regularmente (neutropenia).\nProcurar ajuda perante dor ou vermelhidão ocular (uveíte).\nEvitar álcool durante o tratamento (risco hepático).\nAvisar o médico se usa contraceção hormonal — pode falhar.',
   E'Always take in combination with other antimycobacterials — never as monotherapy.\nMay reduce the effect of many medicines (contraceptives, warfarin, many antiretrovirals) — review all medication.\nMonitor blood counts regularly (neutropenia).\nSeek help for eye pain or redness (uveitis).\nAvoid alcohol during treatment (liver risk).\nTell your doctor if you use hormonal contraception — it may fail.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Rifabutina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c2026b67-4755-4236-96b6-a6b5e7399707',
   'DailyMed/FDA (NIH/NLM) — approved Rifabutin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c2026b67-4755-4236-96b6-a6b5e7399707'),

  ('rivaroxabano',
   'O rivaroxabano é um anticoagulante (dilui o sangue) usado para prevenir AVC em pessoas com fibrilhação auricular, para tratar e prevenir tromboses e embolias, e para prevenir coágulos após cirurgias ortopédicas. Toma-se por via oral, geralmente com alimentos na dose de 15/20 mg.',
   'Rivaroxaban is an anticoagulant (blood thinner) used to prevent stroke in people with atrial fibrillation, to treat and prevent blood clots, and to prevent clots after orthopaedic surgery. It is taken orally, usually with food at the 15/20 mg dose.',
   'Anticoagulante oral de ação direta, inibidor seletivo e reversível do fator Xa. Indicado na prevenção de AVC e embolia sistémica na fibrilhação auricular não valvular, tratamento e prevenção de TVP/EP, profilaxia após artroplastia da anca/joelho e, com aspirina, na prevenção de eventos cardiovasculares na doença arterial coronária/periférica. Biodisponibilidade dose-dependente (completa a 10 mg; ~66% a 20 mg em jejum — tomar com alimentos); eliminação mista (renal e fecal).',
   'Direct-acting oral anticoagulant, selective and reversible inhibitor of factor Xa. Indicated for stroke and systemic embolism prevention in non-valvular atrial fibrillation, treatment and prevention of DVT/PE, prophylaxis after hip/knee arthroplasty and, with aspirin, prevention of cardiovascular events in coronary/peripheral artery disease. Dose-dependent bioavailability (complete at 10 mg; ~66% at 20 mg fasted — take with food); mixed elimination (renal and faecal).',
   E'Redução do risco de AVC e embolia sistémica em adultos com fibrilhação auricular não valvular.\nTratamento da TVP e da EP e prevenção da recorrência.\nProfilaxia da TVP após artroplastia eletiva da anca ou joelho.\nCom aspirina: redução do risco de eventos cardiovasculares major em doentes com doença arterial coronária ou periférica.',
   E'Reduction of the risk of stroke and systemic embolism in adult patients with non-valvular atrial fibrillation.\nTreatment of DVT and PE and prevention of recurrence.\nProphylaxis of DVT following elective hip or knee replacement.\nWith aspirin: reduction of the risk of major cardiovascular events in patients with coronary or peripheral artery disease.',
   E'Hemorragia (a reação mais comum, >5%) — nariz, gengivas, nódoas negras, sangue na urina ou fezes.\nAnemia.\nNáuseas, dor abdominal e dispepsia.\nProcurar ajuda urgente perante hemorragia anormal, vómitos com sangue ou fezes escuras.',
   E'Bleeding (most common reaction, >5%) — nose, gums, bruises, blood in urine or stools.\nAnaemia.\nNausea, abdominal pain and dyspepsia.\nSeek urgent help for abnormal bleeding, vomiting blood or dark stools.',
   E'Tomar as doses de 15 e 20 mg com alimentos (aumenta a absorção); a de 10 mg pode ser com ou sem alimentos.\nNão usar na insuficiência renal grave; ajustar na IR moderada.\nEvitar inibidores/indutores fortes do CYP3A4 e da glicoproteína-P (ex.: cetoconazol, ritonavir, rifampicina).\nAntes de cirurgias ou procedimentos invasivos, informar a equipa.\nSuspender perante hemorragia invulgar e procurar ajuda.\nNão interromper sem indicação (risco de trombose).',
   E'Take the 15 and 20 mg doses with food (increases absorption); the 10 mg dose can be taken with or without food.\nDo not use in severe renal impairment; adjust in moderate renal impairment.\nAvoid strong CYP3A4 and P-glycoprotein inhibitors/inducers (e.g. ketoconazole, ritonavir, rifampicin).\nBefore surgery or invasive procedures, inform the team.\nStop and seek help for unusual bleeding.\nDo not stop without advice (risk of thrombosis).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Rivaroxabano: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=481b7802-5093-43e7-bbd9-1532197eb6e6',
   'DailyMed/FDA (NIH/NLM) — approved Rivaroxaban label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=481b7802-5093-43e7-bbd9-1532197eb6e6'),

  ('salbutamol',
   'O salbutamol é um medicamento de alívio rápido usado para abrir as vias respiratórias na asma e na DPOC (broncodilatador). O inalador é usado quando surgem sintomas (falta de ar, aperto no peito, pieira) ou antes do exercício para prevenir o broncospasmo. É geralmente bem tolerado.',
   'Salbutamol is a fast-relief medicine used to open the airways in asthma and COPD (bronchodilator). The inhaler is used when symptoms occur (shortness of breath, chest tightness, wheezing) or before exercise to prevent bronchospasm. It is generally well tolerated.',
   'Agonista beta-2 adrenérgico seletivo de curta duração (SABA) que relaxa o músculo liso brônquico (ativação da adenilciclase, aumento do AMPc). Broncodilatador de alívio rápido na asma e DPOC e na prevenção do broncospasmo induzido pelo exercício. Efeitos sistémicos dose-dependentes (taquicardia, tremor); o uso regular excessivo é sinal de mau controlo da doença. O inalador MDI (HFA) tem efeito em minutos (pico 50–55 min, duração ~3–6 h).',
   'Selective short-acting beta-2 adrenergic agonist (SABA) that relaxes bronchial smooth muscle (adenyl cyclase activation, increased cAMP). Fast-relief bronchodilator in asthma and COPD and prevention of exercise-induced bronchospasm. Dose-dependent systemic effects (tachycardia, tremor); excessive regular use is a sign of poor disease control. The MDI (HFA) inhaler acts within minutes (peak 50–55 min, duration ~3–6 h).',
   E'Tratamento ou prevenção do broncospasmo com doença obstrutiva reversível das vias aéreas (asma, DPOC) em adultos e crianças ≥4 anos (formulação inalatória).\nPrevenção do broncospasmo induzido pelo exercício.',
   E'Treatment or prevention of bronchospasm with reversible obstructive airway disease (asthma, COPD) in adults and children ≥4 years (inhaled formulation).\nPrevention of exercise-induced bronchospasm.',
   E'Tremor das mãos, nervosismo e cefaleias (frequentes, dose-dependentes).\nTaquicardia e palpitações.\nCãibras musculares.\nIrritação da garganta ou tosse após a inalação.\nHipocaliemia (doses altas).\nProcurar ajuda se o alívio durar menos de 3 horas ou o inalador for usado cada vez mais (mau controlo da asma).',
   E'Hand tremor, nervousness and headache (common, dose-dependent).\nTachycardia and palpitations.\nMuscle cramps.\nThroat irritation or cough after inhalation.\nHypokalaemia (high doses).\nSeek help if relief lasts less than 3 hours or the inhaler is used more and more (poor asthma control).',
   E'Usar no alívio dos sintomas, não como tratamento de manutenção regular da asma (usar o inalador de prevenção prescrito).\nTécnica de inalação correta — ensinar e rever regularmente.\nProcurar ajuda urgente se o alívio não durar 3 horas ou se agravar (crise de asma).\nUsar com cautela em doença cardíaca, hipertiroidismo e diabetes.\nAntes de exercício: 2 inalações 15–30 minutos antes.\nNão exceder a dose prescrita.',
   E'Use for symptom relief, not as regular maintenance treatment of asthma (use the prescribed preventer inhaler).\nCorrect inhalation technique — teach and review regularly.\nSeek urgent help if relief lasts less than 3 hours or worsens (asthma attack).\nUse with caution in heart disease, hyperthyroidism and diabetes.\nBefore exercise: 2 puffs 15–30 minutes beforehand.\nDo not exceed the prescribed dose.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Salbutamol inalador (MDI/HFA): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=583c6408-45cc-9121-e063-6294a90afcc4',
   'DailyMed/FDA (NIH/NLM) — approved Salbutamol inhaler (MDI/HFA) label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=583c6408-45cc-9121-e063-6294a90afcc4'),

  ('sucralfato',
   'O sucralfato é um medicamento que forma uma película protetora sobre a úlcera do estômago ou do duodeno, ajudando-a a cicatrizar. Toma-se por via oral, geralmente 4 vezes ao dia, em jejum (1 hora antes das refeições e ao deitar). Como atua localmente, é pouco absorvido.',
   'Sucralfate is a medicine that forms a protective film over a stomach or duodenal ulcer, helping it heal. It is taken orally, usually 4 times a day, on an empty stomach (1 hour before meals and at bedtime). As it acts locally, it is poorly absorbed.',
   'Complexo de sacarose sulfatada com hidróxido de alumínio que atua localmente: liga-se ao exsudado proteico da úlcera formando uma barreira aderente que impede a difusão de iões de hidrogénio e protege a mucosa. Eficaz no tratamento de curta duração (até 8 semanas) da úlcera duodenal ativa. Absorção mínima; a maior parte é excretada nas fezes. Interage por adsorção com vários fármacos (fluoroquinolonas, digoxina, fenitoína, tetraciclinas) — administrar 2 horas antes.',
   'Sucrose sulphate complex with aluminium hydroxide acting locally: binds to the proteinaceous exudate of the ulcer forming an adherent barrier that prevents hydrogen ion diffusion and protects the mucosa. Effective in the short-term treatment (up to 8 weeks) of active duodenal ulcer. Minimal absorption; most is excreted in the faeces. Interacts by adsorption with several drugs (fluoroquinolones, digoxin, phenytoin, tetracyclines) — administer 2 hours before.',
   E'Tratamento de curta duração (até 8 semanas) da úlcera duodenal ativa.',
   E'Short-term treatment (up to 8 weeks) of active duodenal ulcer.',
   E'Obstipação (a mais frequente, ~2%).\nNáuseas, indigestão, boca seca e flatulência.\nRaramente: reações alérgicas; complicações embólicas fatais descritas com a formulação em suspensão (em doentes críticos).\nAcumulação de alumínio em doentes com IR (uso prolongado).',
   E'Constipation (most common, ~2%).\nNausea, indigestion, dry mouth and flatulence.\nRarely: allergic reactions; fatal embolic complications described with the suspension formulation (in critically ill patients).\nAluminium accumulation in patients with renal impairment (prolonged use).',
   E'Tomar em jejum — 1 hora antes das refeições e ao deitar.\nSeparar 2 horas de outros medicamentos (fluoroquinolonas, digoxina, fenitoína, tetraciclinas, levotiroxina, varfarina) — reduz a absorção.\nUsar com cautela na insuficiência renal (acumulação de alumínio).\nGarantir aporte de líquidos (obstipação).\nSuspender se não houver melhoria após 8 semanas (reavaliar diagnóstico).',
   E'Take on an empty stomach — 1 hour before meals and at bedtime.\nSeparate by 2 hours from other medicines (fluoroquinolones, digoxin, phenytoin, tetracyclines, levothyroxine, warfarin) — reduces absorption.\nUse with caution in renal impairment (aluminium accumulation).\nEnsure adequate fluids (constipation).\nStop if no improvement after 8 weeks (reassess diagnosis).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Sucralfato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1e781cc0-24ec-4028-8262-dcef9873ea1f',
   'DailyMed/FDA (NIH/NLM) — approved Sucralfate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1e781cc0-24ec-4028-8262-dcef9873ea1f'),

  ('dextrometorfano',
   'O dextrometorfano é um antitússico usado para aliviar temporariamente a tosse seca em constipações e irritações das vias respiratórias. Está disponível sem receita médica. Não deve ser usado em tosse com expetoração abundante nem por mais de 7 dias.',
   'Dextromethorphan is a cough suppressant used to temporarily relieve dry cough in colds and airway irritation. It is available without prescription. It should not be used for cough with lots of phlegm or for more than 7 days.',
   'Antitússico de ação central (derivado do levorfanol, sem atividade opioide analgésica significativa) que eleva o limiar da tosse no centro da tosse do tronco cerebral. Metabolitizado principalmente pelo CYP2D6 em dextrorfano (o metabolito ativo) — polimorfismo genético e inibidores (quinidina, ISRS) alteram muito a exposição. Não usar com IMAO; risco de síndrome serotoninérgica com ISRS/ISRN e de abuso em doses altas.',
   'Centrally acting antitussive (levorphanol derivative, without significant opioid analgesic activity) that raises the cough threshold in the brainstem cough centre. Mainly metabolised by CYP2D6 to dextrorphan (the active metabolite) — genetic polymorphism and inhibitors (quinidine, SSRIs) greatly alter exposure. Do not use with MAO inhibitors; risk of serotonin syndrome with SSRIs/SNRIs and of abuse at high doses.',
   E'Alívio temporário da tosse devida a irritação menor da garganta e dos brônquios, como na constipação comum.',
   E'Temporarily relieves cough due to minor throat and bronchial irritation, as may occur with the common cold.',
   E'Sonolência, tonturas e fadiga (de expressão ligeira).\nNáuseas e vómitos.\nExcitação, confusão e depressão respiratória na sobredosagem.\nRaramente: reações alérgicas; síndrome serotoninérgica com ISRS (agitação, febre, tremores).',
   E'Drowsiness, dizziness and fatigue (mild).\nNausea and vomiting.\nExcitement, confusion and respiratory depression in overdose.\nRarely: allergic reactions; serotonin syndrome with SSRIs (agitation, fever, tremor).',
   E'Não usar com inibidores da MAO (ou nas 2 semanas após parar).\nNão usar em tosse persistente ou crónica (asma, tabagismo, enfisema), tosse com muita expetoração, ou por mais de 7 dias sem avaliação.\nUsar com cautela com ISRS/ISRN, quinidina e amiodarona (síndrome serotoninérgica).\nNão exceder a dose recomendada (risco de abuso e depressão respiratória).\nCuidado na condução (sonolência).',
   E'Do not use with MAO inhibitors (or within 2 weeks of stopping).\nDo not use for persistent or chronic cough (asthma, smoking, emphysema), cough with lots of phlegm, or for more than 7 days without assessment.\nUse with caution with SSRIs/SNRIs, quinidine and amiodarone (serotonin syndrome).\nDo not exceed the recommended dose (risk of abuse and respiratory depression).\nTake care when driving (drowsiness).',
   'DailyMed/FDA (NIH/NLM) — rótulo OTC Dextrometorfano (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0d99237c-0b52-0af6-e063-6394a90aba14',
   'DailyMed/FDA (NIH/NLM) — OTC Dextromethorphan label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0d99237c-0b52-0af6-e063-6394a90aba14'),

  ('difenidramina',
   'A difenidramina é um anti-histamínico usado para aliviar os sintomas de alergia (espirros, corrimento nasal, comichão) e como auxiliar do sono. É um anti-histamínico de primeira geração: causa sonolência marcada. Deve evitar-se conduzir ou operar máquinas depois de a tomar.',
   'Diphenhydramine is an antihistamine used to relieve allergy symptoms (sneezing, runny nose, itching) and as a sleep aid. It is a first-generation antihistamine: it causes marked drowsiness. You should avoid driving or operating machinery after taking it.',
   'Anti-histamínico H1 de primeira geração (etanolamina) com marcado efeito sedativo e propriedades antimuscarínicas e antieméticas. Atravessa a barreira hematoencefálica (sedação) e bloqueia os efeitos centrais da histamina. Sofre metabolismo de primeira passagem hepática importante (CYP2D6) e eliminação renal. Usado nas alergias, urticária, cinetose e como hipnótico ocasional; também antitússico (combinações) e antipruriginoso tópico.',
   'First-generation H1 antihistamine (ethanolamine) with marked sedative effect and antimuscarinic and antiemetic properties. Crosses the blood-brain barrier (sedation) and blocks central histamine effects. Undergoes significant hepatic first-pass metabolism (CYP2D6) and renal elimination. Used in allergies, urticaria, motion sickness and as an occasional hypnotic; also antitussive (combinations) and topical antipruritic.',
   E'Alívio temporário dos sintomas da rinite alérgica (corrimento nasal, espirros, comichão nos olhos, nariz ou garganta).\nAlívio temporário dos sintomas da constipação comum.\n(Como auxiliar do sono em algumas formulações; e, sob prescrição, cinetose e reações alérgicas.)',
   E'Temporary relief of hay fever or upper respiratory allergy symptoms (runny nose, sneezing, itchy watery eyes, itching of the nose or throat).\nTemporary relief of common cold symptoms.\n(As a sleep aid in some formulations; and, by prescription, motion sickness and allergic reactions.)',
   E'Sonolência marcada (o efeito mais frequente).\nBoca seca, obstipação, visão turva e dificuldade em urinar (efeitos antimuscarínicos).\nExcitação paradoxal, sobretudo em crianças e idosos.\nTonturas e diminuição da concentração.\nConfusão e maior risco de quedas nos idosos.',
   E'Marked drowsiness (the most frequent effect).\nDry mouth, constipation, blurred vision and difficulty urinating (antimuscarinic effects).\nParadoxical excitement, especially in children and the elderly.\nDizziness and reduced concentration.\nConfusion and increased fall risk in the elderly.',
   E'Não usar para fazer dormir uma criança.\nEvitar álcool, sedativos e tranquilizantes (aumentam a sonolência).\nNão conduzir nem operar máquinas durante o tratamento.\nPerguntar ao médico antes de usar com doença respiratória (enfisema, bronquite crónica), glaucoma, dificuldade em urinar por próstata.\nEvitar nos idosos quando possível (confusão, quedas).\nNão usar em simultâneo com outros produtos contendo difenidramina (incluindo uso tópico).',
   E'Do not use to make a child sleepy.\nAvoid alcohol, sedatives and tranquillisers (increase drowsiness).\nDo not drive or operate machinery during treatment.\nAsk a doctor before use with respiratory disease (emphysema, chronic bronchitis), glaucoma, difficulty urinating due to prostate problems.\nAvoid in the elderly when possible (confusion, falls).\nDo not use with other diphenhydramine-containing products (including topical use).',
   'DailyMed/FDA (NIH/NLM) — rótulo OTC Difenidramina (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f1e83e43-011c-4470-bd55-fb2818a9fc84',
   'DailyMed/FDA (NIH/NLM) — OTC Diphenhydramine label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f1e83e43-011c-4470-bd55-fb2818a9fc84'),

  ('artesunato-amodiaquina',
   'O artesunato + amodiaquina é um medicamento combinado usado no tratamento da malária não complicada por Plasmodium falciparum. Toma-se por via oral durante 3 dias, com as doses ajustadas ao peso. O tratamento completo é essencial para curar a infeção e evitar resistências.',
   'Artesunate + amodiaquine is a combination medicine used to treat uncomplicated Plasmodium falciparum malaria. It is taken orally for 3 days, with doses adjusted by weight. Completing the full course is essential to cure the infection and prevent resistance.',
   'Terapêutica combinada à base de artemisinina (ACT) de dose fixa: o artesunato (pró-fármaco da diidroartemisinina, DHA) elimina rapidamente a parasitemia; a amodiaquina (4-aminoquinolina, ativa também contra estirpes resistentes à cloroquina) proporciona a ação prolongada que elimina os parasitas remanescentes. Indicada no tratamento da malária não complicada por P. falciparum suscetível. A amodiaquina associa-se a risco de agranulocitose e hepatotoxicidade (mais relevantes na profilaxia prolongada — não indicada).',
   'Fixed-dose artemisinin-based combination therapy (ACT): artesunate (prodrug of dihydroartemisinin, DHA) rapidly clears parasitaemia; amodiaquine (4-aminoquinoline, also active against chloroquine-resistant strains) provides the prolonged action that clears remaining parasites. Indicated for the treatment of uncomplicated P. falciparum malaria. Amodiaquine is associated with risk of agranulocytosis and hepatotoxicity (more relevant in prolonged prophylaxis — not indicated).',
   E'Tratamento da malária não complicada por Plasmodium falciparum suscetível à amodiaquina e ao artesunato.\nPode ser considerada em programas de administração massiva de medicamentos para reduzir a transmissão ou a carga de doença por P. falciparum.',
   E'Treatment of uncomplicated malaria due to Plasmodium falciparum susceptible to amodiaquine and artesunate.\nMay be considered as part of mass drug administration programmes to reduce the transmissibility or disease burden of P. falciparum.',
   E'Anorexia, dor abdominal, náuseas, astenia, sonolência, insónia e tosse (as mais frequentes).\nAnemia, astenia e vertigens (as reações graves mais frequentes).\nHipoglicemia (pouco frequente) — vigiar em crianças e doentes debilitados.\nLeucopenia, neutropenia e, raramente, agranulocitose potencialmente fatal (amodiaquina).\nHepatotoxicidade com lesão hepática prévia (amodiaquina).\nAlucinações (pouco frequentes).',
   E'Anorexia, abdominal pain, nausea, asthenia, somnolence, insomnia and cough (most frequent).\nAnaemia, asthenia and vertigo (most frequent serious reactions).\nHypoglycaemia (uncommon) — monitor in children and debilitated patients.\nLeukopenia, neutropenia and, rarely, potentially fatal agranulocytosis (amodiaquine).\nHepatotoxicity with previous liver injury (amodiaquine).\nHallucinations (uncommon).',
   E'Cumprir o esquema completo de 3 dias — interromper cedo deixa parasitas e favorece resistências.\nNão usar na profilaxia da malária (risco de agranulocitose e toxicidade hepática).\nContraindicado em caso de hipersensibilidade, história de lesão hepática ou acontecimento hematológico durante tratamento prévio com amodiaquina, e retinopatia (tratamentos frequentes).\nNão usar em regiões com resistência disseminada à amodiaquina.\nVigiar sinais de infeção ou hemorragia (agranulocitose) e icterícia.\nNão recomendado na malária complicada nem em doentes com défice de G6PD conhecido sem avaliação.',
   E'Complete the full 3-day course — stopping early leaves parasites and favours resistance.\nDo not use for malaria prophylaxis (risk of agranulocytosis and liver toxicity).\nContraindicated in hypersensitivity, history of liver injury or haematological event during previous amodiaquine treatment, and retinopathy (frequent treatment).\nDo not use in regions with widespread amodiaquine resistance.\nMonitor for signs of infection or bleeding (agranulocytosis) and jaundice.\nNot recommended in complicated malaria or in patients with known G6PD deficiency without assessment.',
   'SmPC WHO-prequalificada — Artesunate/Amodiaquine (Cipla, MA102), secções 4.1, 4.3, 4.4, 4.8: https://extranet.who.int/prequal/sites/default/files/whopar_files/MA102part4.pdf',
   'WHO-prequalified SmPC — Artesunate/Amodiaquine (Cipla, MA102), sections 4.1, 4.3, 4.4, 4.8: https://extranet.who.int/prequal/sites/default/files/whopar_files/MA102part4.pdf')
) AS v(slug, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
        indications_pt, indications_en, side_effects_pt, side_effects_en,
        precautions_pt, precautions_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;

-- =====================================================================
-- Farmacologia (drug_pharmacology) — mesma ordem de fármacos
-- =====================================================================
INSERT INTO public.drug_pharmacology
  (drug_id, pharmacodynamics_pt, pharmacodynamics_en, mechanism_pt, mechanism_en,
   metabolism_pt, metabolism_en, absorption_pt, absorption_en,
   half_life_pt, half_life_en, source_pt, source_en, status)
SELECT d.id, v.pharmacodynamics_pt, v.pharmacodynamics_en, v.mechanism_pt, v.mechanism_en,
       v.metabolism_pt, v.metabolism_en, v.absorption_pt, v.absorption_en,
       v.half_life_pt, v.half_life_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('alendronato',
   'Bifosfonato antirreabsortivo: liga-se à hidroxiapatite óssea e inibe especificamente a atividade dos osteoclastos, as células que reabsorvem o osso. Reduz a remodelação óssea (o número de locais em que o osso é remodelado), com a formação a exceder a reabsorção, conduzindo a ganhos progressivos de massa óssea. Doses orais diárias de 5–40 mg produzem alterações bioquímicas indicativas de inibição dose-dependente da reabsorção (diminuição do cálcio urinário e dos marcadores de degradação do colagénio).',
   'Antiresorptive bisphosphonate: binds to bone hydroxyapatite and specifically inhibits the activity of osteoclasts, the bone-resorbing cells. Reduces bone turnover (the number of sites at which bone is remodelled), with formation exceeding resorption, leading to progressive gains in bone mass. Daily oral doses of 5–40 mg produce biochemical changes indicative of dose-dependent inhibition of resorption (decreased urinary calcium and collagen degradation markers).',
   'A nível celular, o alendronato localiza-se preferencialmente nos locais de reabsorção óssea, sob os osteoclastos. Os osteoclastos aderem normalmente à superfície óssea mas perdem a borda em escova característica da reabsorção ativa — o alendronato não interfere com o recrutamento ou adesão dos osteoclastos, mas inibe a sua atividade. O alendronato incorporado na matriz óssea não é farmacologicamente ativo, pelo que deve ser administrado de forma contínua.',
   'At the cellular level, alendronate localises preferentially to sites of bone resorption, under the osteoclasts. The osteoclasts adhere normally to the bone surface but lack the ruffled border indicative of active resorption — alendronate does not interfere with osteoclast recruitment or attachment, but inhibits their activity. Alendronate incorporated into the bone matrix is not pharmacologically active, so it must be administered continuously.',
   'Não há evidência de que o alendronato seja metabolizado em animais ou humanos. A excreção é renal: após uma dose intravenosa única de 14C-alendronato, aproximadamente 50% da radioatividade foi excretada na urina em 72 horas e pouco ou nada nas fezes. A depuração renal foi de 71 mL/min e a depuração sistémica não excedeu 200 mL/min.',
   'There is no evidence that alendronate is metabolised in animals or humans. Excretion is renal: after a single intravenous 14C-alendronate dose, approximately 50% of the radioactivity was excreted in the urine within 72 hours and little or none in the faeces. Renal clearance was 71 mL/min and systemic clearance did not exceed 200 mL/min.',
   'A biodisponibilidade oral média é de apenas 0,64% (mulheres) e 0,59% (homens) quando administrado em jejum noturno e 2 horas antes de um pequeno-almoço padronizado. A biodisponibilidade diminui cerca de 40% quando administrado 0,5 ou 1 hora antes do pequeno-almoço, e é negligenciável com ou até 2 horas após a refeição. Café e sumo de laranja reduzem-na em cerca de 60%. A ligação às proteínas plasmáticas é de ~78%.',
   'Mean oral bioavailability is only 0.64% (women) and 0.59% (men) when administered after an overnight fast and 2 hours before a standardised breakfast. Bioavailability decreases by approximately 40% when given 0.5 or 1 hour before breakfast, and is negligible with or up to 2 hours after a meal. Coffee and orange juice reduce it by about 60%. Plasma protein binding is ~78%.',
   'A semivida terminal em humanos é estimada em mais de 10 anos, refletindo provavelmente a libertação do alendronato a partir do esqueleto. As concentrações plasmáticas após doses orais terapêuticas são demasiado baixas (<5 ng/mL) para deteção analítica. Após 10 anos de tratamento oral (10 mg/dia), estima-se que a quantidade libertada diariamente do esqueleto seja ~25% da absorvida.',
   'The terminal half-life in humans is estimated to exceed 10 years, probably reflecting release of alendronate from the skeleton. Plasma concentrations after therapeutic oral doses are too low (<5 ng/mL) for analytical detection. After 10 years of oral treatment (10 mg/day), the amount released daily from the skeleton is estimated at ~25% of that absorbed.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Alendronato sódico, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ffdd2496-d253-419b-85a6-8c615f7545f1',
   'DailyMed/FDA (NIH/NLM) — approved Alendronate sodium label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ffdd2496-d253-419b-85a6-8c615f7545f1'),

  ('alopurinol',
   'Reduz a produção de ácido úrico por inibição da xantina-oxidase, a enzima que converte hipoxantina em xantina e xantina em ácido úrico. Esta inibição diminui a uricemia e a uricúria, prevenindo os depósitos de urato (crises de gota, tofos, litíase) e a nefropatia úrica.',
   'Reduces uric acid production by inhibiting xanthine oxidase, the enzyme that converts hypoxanthine to xanthine and xanthine to uric acid. This inhibition lowers serum and urinary uric acid, preventing urate deposits (gout flares, tophi, lithiasis) and uric acid nephropathy.',
   'O alopurinol e o seu metabolito principal ativo, o oxipurinol (aloxantina), são ambos inibidores da xantina-oxidase. O oxipurinol é também eliminado por reabsorção tubular, prolongando o efeito inibitório para além da semivida do fármaco-mãe.',
   'Allopurinol and its principal active metabolite, oxypurinol (alloxanthine), are both inhibitors of xanthine oxidase. Oxypurinol is also eliminated by tubular reabsorption, extending the inhibitory effect beyond the half-life of the parent drug.',
   'O alopurinol é metabolizado no metabolito ativo oxipurinol, também inibidor da xantina-oxidase. Aproximadamente 20% do alopurinol ingerido é excretado nas fezes; o oxipurinol é eliminado principalmente inalterado na urina por filtração glomerular e reabsorção tubular.',
   'Allopurinol is metabolised to the active metabolite oxypurinol, also a xanthine oxidase inhibitor. Approximately 20% of ingested allopurinol is excreted in the faeces; oxypurinol is eliminated primarily unchanged in urine by glomerular filtration and tubular reabsorption.',
   'O alopurinol é absorvido em cerca de 90% pelo trato gastrointestinal. Os picos plasmáticos ocorrem geralmente às 1,5 horas (alopurinol) e 4,5 horas (oxipurinol). Após uma dose oral única de 300 mg, os níveis plasmáticos máximos são de cerca de 3 mcg/mL de alopurinol e 6,5 mcg/mL de oxipurinol.',
   'Allopurinol is approximately 90% absorbed from the gastrointestinal tract. Peak plasma levels generally occur at 1.5 hours (allopurinol) and 4.5 hours (oxypurinol). After a single oral 300 mg dose, maximum plasma levels are about 3 mcg/mL of allopurinol and 6.5 mcg/mL of oxypurinol.',
   'A semivida do alopurinol é de aproximadamente 1–2 horas; a do seu metabolito ativo oxipurinol é de cerca de 15 horas após dose oral.',
   'The half-life of allopurinol is approximately 1–2 hours; that of its active metabolite oxypurinol is about 15 hours after an oral dose.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Alopurinol, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=583df4b8-a1d4-01ed-e063-6394a90af007',
   'DailyMed/FDA (NIH/NLM) — approved Allopurinol label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=583df4b8-a1d4-01ed-e063-6394a90af007'),

  ('apixabano',
   'Anticoagulante oral de ação direta que inibe seletiva e reversivelmente o fator Xa, no vértice da via de coagulação intrínseca e extrínseca. A inibição do fator Xa reduz a geração de trombina e a formação do trombo, sem necessidade de antitrombina III nem de monitorização de rotina da coagulação.',
   'Direct-acting oral anticoagulant that selectively and reversibly inhibits factor Xa, at the apex of the intrinsic and extrinsic coagulation pathways. Factor Xa inhibition reduces thrombin generation and thrombus formation, without requiring antithrombin III or routine coagulation monitoring.',
   'O apixabano liga-se diretamente ao sítio ativo do fator Xa, impedindo a conversão da protrombina em trombina (fator IIa). A farmacodinâmica avalia-se pela inibição da atividade anti-Xa; não inibe a trombina (fator IIa) diretamente nem afeta a agregação plaquetária.',
   'Apixaban binds directly to the active site of factor Xa, preventing the conversion of prothrombin to thrombin (factor IIa). Pharmacodynamics are assessed by anti-Xa activity inhibition; it does not inhibit thrombin (factor IIa) directly nor affect platelet aggregation.',
   'Cerca de 25% da dose oral é recuperada na urina e fezes como metabolitos. É metabolizado principalmente pelo CYP3A4, com contribuições menores do CYP1A2, 2C8, 2C9, 2C19 e 2J2; a O-desmetilação e a hidroxilação são os principais locais de biotransformação. O apixabano inalterado é o principal componente no plasma — não há metabolitos ativos circulantes.',
   'Approximately 25% of an oral dose is recovered in urine and faeces as metabolites. It is metabolised mainly via CYP3A4, with minor contributions from CYP1A2, 2C8, 2C9, 2C19 and 2J2; O-demethylation and hydroxylation are the major sites of biotransformation. Unchanged apixaban is the major plasma component — there are no active circulating metabolites.',
   'A biodisponibilidade absoluta é de aproximadamente 50% para doses até 10 mg, com concentrações máximas 3–4 horas após a administração oral; os alimentos não afetam a biodisponibilidade. A ligação às proteínas plasmáticas é de ~87% e o volume de distribuição é de ~21 L. A absorção é limitada pela dissolução em doses ≥25 mg.',
   'Absolute bioavailability is approximately 50% for doses up to 10 mg, with peak concentrations 3–4 hours after oral administration; food does not affect bioavailability. Plasma protein binding is ~87% and the volume of distribution is ~21 L. Absorption is dissolution-limited at doses ≥25 mg.',
   'O apixabano tem uma depuração total de aproximadamente 3,3 L/hora e uma semivida aparente de cerca de 12 horas. A excreção renal representa cerca de 27% da depuração total; o restante é eliminado por via biliar e intestinal direta nas fezes.',
   'Apixaban has a total clearance of approximately 3.3 L/hour and an apparent half-life of about 12 hours. Renal excretion accounts for about 27% of total clearance; the remainder is eliminated by biliary and direct intestinal excretion in the faeces.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Apixabano (ELIQUIS), secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a454cd24-0c6d-46e8-b1e4-197388606175',
   'DailyMed/FDA (NIH/NLM) — approved Apixaban (ELIQUIS) label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a454cd24-0c6d-46e8-b1e4-197388606175'),

  ('atazanavir',
   'Inibidor da protease do VIH-1 (IP) que impede a clivagem dos precursores proteicos gag e gag-pol no virião imaturo, bloqueando a maturação e a infecciosidade dos novos vírions. Em associação com outros antirretrovirais reduz a carga viral e aumenta os linfócitos CD4. Prolonga o intervalo PR e eleva a bilirrubina indireta (icterícia benigna).',
   'HIV-1 protease inhibitor (PI) that prevents the cleavage of gag and gag-pol protein precursors in the immature virion, blocking the maturation and infectivity of new virions. In combination with other antiretrovirals it reduces viral load and increases CD4 lymphocytes. Prolongs the PR interval and raises indirect bilirubin (benign jaundice).',
   'Liga-se ao sítio ativo da protease do VIH-1, impedindo a clivagem das poliproteínas virais — os vírions resultantes são imaturos e não infecciosos. A farmacocinética é não linear (aumentos mais que proporcionais da AUC e Cmax entre 200 e 800 mg/dia), com Tmax de ~2,5 horas e estado estacionário aos 4–8 dias.',
   'Binds to the active site of HIV-1 protease, preventing cleavage of viral polyproteins — the resulting virions are immature and non-infectious. Pharmacokinetics are non-linear (greater than dose-proportional increases in AUC and Cmax between 200 and 800 mg/day), with a Tmax of ~2.5 hours and steady state at 4–8 days.',
   'O atazanavir é extensamente metabolizado no fígado, principalmente por mono-oxigenação e dioxigenação (CYP3A4); vias menores incluem glucuronidação, N-desalquilação e hidrólise. É inibidor moderado do CYP3A4 e substrato do mesmo enzima e da glicoproteína-P.',
   'Atazanavir is extensively metabolised in the liver, mainly by mono-oxygenation and dioxygenation (CYP3A4); minor pathways include glucuronidation, N-dealkylation and hydrolysis. It is a moderate CYP3A4 inhibitor and a substrate of the same enzyme and of P-glycoprotein.',
   'O atazanavir é rapidamente absorvido (Tmax ~2,5 horas). Os alimentos aumentam a biodisponibilidade e reduzem a variabilidade: uma refeição ligeira aumenta a AUC em 70% e a Cmax em 57% em jejum. A ligação às proteínas séricas é de 86%, independente da concentração (albumina e alfa-1-glicoproteína ácida).',
   'Atazanavir is rapidly absorbed (Tmax ~2.5 hours). Food increases bioavailability and reduces variability: a light meal increases AUC by 70% and Cmax by 57% relative to fasting. Serum protein binding is 86%, concentration-independent (albumin and alpha-1-acid glycoprotein).',
   'A semivida de eliminação (t½) é de ~7,9 horas com 400 mg uma vez ao dia, aumentando para ~18 horas quando potenciado com ritonavir 100 mg (300 mg/dia). O estado estacionário é atingido entre os dias 4 e 8, com acumulação de ~2,3 vezes.',
   'The elimination half-life (t½) is ~7.9 hours with 400 mg once daily, increasing to ~18 hours when boosted with ritonavir 100 mg (300 mg/day). Steady state is reached between days 4 and 8, with ~2.3-fold accumulation.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Atazanavir (REYATAZ), secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=165cff62-b284-4a27-a65d-9ec8a5bfcdd8',
   'DailyMed/FDA (NIH/NLM) — approved Atazanavir (REYATAZ) label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=165cff62-b284-4a27-a65d-9ec8a5bfcdd8'),

  ('azatioprina',
   'Imunossupressor antimetabólito: inibe a síntese de purinas (via 6-tioguanina) e a proliferação de linfócitos, suprimindo as hipersensibilidades de tipo celular e alterando a produção de anticorpos. A magnitude e a duração dos efeitos clínicos correlacionam-se com os níveis de nucleótidos tiopurínicos nos tecidos, não com os níveis plasmáticos.',
   'Immunosuppressive antimetabolite: inhibits purine synthesis (via 6-thioguanine) and lymphocyte proliferation, suppressing cell-mediated hypersensitivities and altering antibody production. The magnitude and duration of clinical effects correlate with thiopurine nucleotide levels in tissues, not with plasma levels.',
   'A azatioprina é um pró-fármaco da 6-mercaptopurina (6-MP). A 6-MP é ativada pela hipoxantina-guanina fosforribosiltransferase (HGPRT) e por cinases em nucleótidos 6-tioguanina (6-TGN), cuja incorporação no ADN é responsável pela citotoxicidade. As vias de inativação principais são a tiol-metilação pela TPMT e a oxidação pela xantina-oxidase.',
   'Azathioprine is a prodrug of 6-mercaptopurine (6-MP). 6-MP is activated by hypoxanthine-guanine phosphoribosyltransferase (HGPRT) and kinases to 6-thioguanine nucleotides (6-TGNs), whose incorporation into DNA is responsible for cytotoxicity. The main inactivation routes are thiol methylation by TPMT and oxidation by xanthine oxidase.',
   'A azatioprina é bem absorvida; a radioatividade máxima no soro ocorre 1–2 horas após a dose oral. É metabolizada a 6-mercaptopurina e, depois, oxidada ou metilada nos eritrócitos e no fígado — não é detetável na urina após 8 horas. O défice de TPMT ou NUDT15 aumenta muito os níveis de 6-TGN e o risco de mielossupressão.',
   'Azathioprine is well absorbed; maximum serum radioactivity occurs 1–2 hours after an oral dose. It is metabolised to 6-mercaptopurine and then oxidised or methylated in erythrocytes and the liver — it is undetectable in urine after 8 hours. TPMT or NUDT15 deficiency greatly increases 6-TGN levels and the risk of myelosuppression.',
   'A azatioprina é bem absorvida após administração oral, com pico de radioatividade sérica 1–2 horas após a dose. A azatioprina e a mercaptopurina ligam-se moderadamente às proteínas séricas (~30%) e são parcialmente dialisáveis.',
   'Azathioprine is well absorbed following oral administration, with peak serum radioactivity 1–2 hours after the dose. Azathioprine and mercaptopurine are moderately bound to serum proteins (~30%) and are partially dialysable.',
   'A radioatividade total (fármaco + metabolitos marcados) decai com uma semivida de ~5 horas — não é a semivida da azatioprina em si, mas a taxa de decaimento de todos os metabolitos contendo 35S. As doses habituais produzem níveis sanguíneos baixos (<1 mcg/mL).',
   'Total radioactivity (drug + labelled metabolites) decays with a half-life of ~5 hours — not an estimate of the half-life of azathioprine itself, but the decay rate for all 35S-containing metabolites. Usual doses produce low blood levels (<1 mcg/mL).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Azatioprina, secção Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5116b22b-1460-5535-e063-6394a90acbe5',
   'DailyMed/FDA (NIH/NLM) — approved Azathioprine label, Clinical Pharmacology section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5116b22b-1460-5535-e063-6394a90acbe5'),

  ('bedaquilina',
   'Antimicobacteriano diarilquinolínico com mecanismo de ação específico e novo: inibe a ATP-sintase micobacteriana (subunidade c), bloqueando a produção de energia (ATP) da micobactéria. É ativo contra Mycobacterium tuberculosis, incluindo estirpes multirresistentes, com especificidade para micobactérias.',
   'Diarylquinoline antimycobacterial with a specific and novel mechanism of action: inhibits the mycobacterial ATP synthase (c subunit), blocking the energy (ATP) production of the mycobacterium. Active against Mycobacterium tuberculosis, including multidrug-resistant strains, with specificity for mycobacteria.',
   'A bedaquilina liga-se à subunidade c da ATP-sintase (F0F1) micobacteriana, impedindo a síntese de ATP — a micobactéria perde a sua principal fonte de energia e morre. Este alvo é diferente dos das classes antituberculosas clássicas, o que explica a atividade contra estirpes resistentes.',
   'Bedaquiline binds to the c subunit of the mycobacterial ATP synthase (F0F1), preventing ATP synthesis — the mycobacterium loses its main energy source and dies. This target differs from those of the classical antituberculosis classes, explaining activity against resistant strains.',
   'A bedaquilina é metabolizada principalmente pelo CYP3A4 no metabolito N-monodesmetil (M2), com exposição relativa de M2 de 23–31%. A excreção é predominantemente fecal; a excreção renal de fármaco inalterado é ≤0,001% da dose.',
   'Bedaquiline is metabolised mainly by CYP3A4 to the N-monodesmethyl metabolite (M2), with a relative M2 exposure of 23–31%. Excretion is predominantly faecal; renal excretion of unchanged drug is ≤0.001% of the dose.',
   'Uma refeição rica em gordura (22 g de gordura, 558 kcal) aumenta a Cmax e a AUC em 2 vezes — o medicamento deve ser tomado com alimentos para aumentar a biodisponibilidade oral. O Tmax é de cerca de 5 horas após dose oral única.',
   'A high-fat meal (22 grams of fat, 558 total kcal) increased Cmax and AUC by 2-fold — the medicine should be taken with food to enhance oral bioavailability. Tmax is around 5 hours after a single oral dose.',
   'A semivida terminal é muito longa: aproximadamente 5,5 meses, tanto para a bedaquilina como para o metabolito M2. A ligação às proteínas plasmáticas é >99,9% e o volume de distribuição aparente é de ~117 L.',
   'The terminal half-life is very long: approximately 5.5 months, for both bedaquiline and the M2 metabolite. Plasma protein binding is >99.9% and the apparent volume of distribution is ~117 L.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Bedaquilina (SIRTURO), secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1534c9ae-4948-4cf4-9f66-222a99db6d0e',
   'DailyMed/FDA (NIH/NLM) — approved Bedaquiline (SIRTURO) label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1534c9ae-4948-4cf4-9f66-222a99db6d0e'),

  ('calcitriol',
   'Vitamina D ativa (1,25-di-hidroxicolecalciferol): aumenta a absorção intestinal de cálcio, a reabsorção renal de cálcio e fósforo e a mobilização óssea, elevando o cálcio sérico e suprimindo a secreção de paratormona (PTH). Reduz a fosfatase alcalina e as manifestações histológicas da osteíte fibrosa cística na doença renal.',
   'Active vitamin D (1,25-dihydroxycholecalciferol): increases intestinal calcium absorption, renal calcium and phosphate reabsorption and bone mobilisation, raising serum calcium and suppressing parathyroid hormone (PTH) secretion. Reduces alkaline phosphatase and the histological manifestations of osteitis fibrosa cystica in renal disease.',
   'O calcitriol atua ligando-se ao recetor da vitamina D (VDR), um recetor nuclear que regula a transcrição de genes envolvidos no transporte de cálcio (ex.: proteínas de ligação ao cálcio intestinais). Ao contrário da vitamina D nativa, o calcitriol não depende da hidroxilação renal (1-alfa) para se tornar ativo — daí a sua eficácia na doença renal.',
   'Calcitriol acts by binding to the vitamin D receptor (VDR), a nuclear receptor that regulates transcription of genes involved in calcium transport (e.g. intestinal calcium-binding proteins). Unlike native vitamin D, calcitriol does not depend on renal (1-alpha) hydroxylation to become active — hence its efficacy in renal disease.',
   'O calcitriol é eliminado por vias metabólicas e biliares; na insuficiência renal, a semivida de eliminação aumenta pelo menos 2 vezes em comparação com sujeitos saudáveis. Em doentes com síndrome nefrótica e em hemodiálise, os níveis séricos pré-dose e de pico são mais baixos.',
   'Calcitriol is eliminated by metabolic and biliary routes; in renal failure, the elimination half-life increases by at least two-fold compared with healthy subjects. In patients with nephrotic syndrome and haemodialysis, predose and peak serum levels are lower.',
   'O calcitriol oral é absorvido no intestino delgado. Em doentes pediátricos em diálise peritoneal (dose média 10,2 ng/kg), a Cmax média foi de 116 pmol/L; em doentes com síndrome nefrótica os picos séricos foram atingidos às 4 horas e em hemodiálise às 8–12 horas.',
   'Oral calcitriol is absorbed in the small intestine. In paediatric patients on peritoneal dialysis (mean dose 10.2 ng/kg), mean Cmax was 116 pmol/L; in patients with nephrotic syndrome peak serum levels were reached at 4 hours and in haemodialysis at 8–12 hours.',
   'A semivida sérica média do calcitriol foi de ~27,4 horas em doentes pediátricos em diálise peritoneal; em doentes em hemodiálise foi estimada em 16,2–21,9 horas e em doentes com síndrome nefrótica em ~21,9 horas (cerca do dobro da de sujeitos saudáveis).',
   'Mean serum calcitriol half-life was ~27.4 hours in paediatric patients on peritoneal dialysis; in haemodialysis patients it was estimated at 16.2–21.9 hours and in nephrotic syndrome patients at ~21.9 hours (about twice that of healthy subjects).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Calcitriol, secção Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8465337c-86ca-ea9d-e053-2991aa0ab167',
   'DailyMed/FDA (NIH/NLM) — approved Calcitriol label, Clinical Pharmacology section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8465337c-86ca-ea9d-e053-2991aa0ab167'),

  ('captopril',
   'Inibidor da enzima de conversão da angiotensina (IECA): reduz a formação de angiotensina II e aumenta a bradicinina, diminuindo a resistência vascular periférica e a pressão arterial. Na hipertensão não altera habitualmente o débito cardíaco; aumenta o fluxo renal. A redução da pressão é máxima 60–90 minutos após a dose oral; o efeito é dose-dependente e pode ser progressivo ao longo de semanas.',
   'Angiotensin-converting enzyme inhibitor (ACEI): reduces angiotensin II formation and increases bradykinin, lowering peripheral vascular resistance and blood pressure. In hypertension it usually does not change cardiac output; it increases renal blood flow. Blood pressure reduction is maximal 60–90 minutes after an oral dose; the effect is dose-dependent and may be progressive over weeks.',
   'O captopril bloqueia a conversão da angiotensina I em angiotensina II (potente vasoconstritor e estímulo da aldosterona) e reduz a degradação da bradicinina (vasodilatador). O efeito hipotensor dos IECA adiciona-se ao dos diuréticos tiazídicos, mas é menos que aditivo com os betabloqueadores.',
   'Captopril blocks the conversion of angiotensin I to angiotensin II (a potent vasoconstrictor and aldosterone stimulus) and reduces the degradation of bradykinin (a vasodilator). The antihypertensive effect of ACEIs adds to that of thiazide diuretics, but is less than additive with beta-blockers.',
   'O captopril é parcialmente metabolizado: na urina de 24 horas, 40–50% é fármaco inalterado, e a maior parte do restante é o dímero dissulfureto do captopril e o dissulfureto captopril-cisteína. Mais de 95% da dose absorvida é eliminada na urina em 24 horas; na insuficiência renal há retenção.',
   'Captopril is partially metabolised: in 24-hour urine, 40–50% is unchanged drug, and most of the remainder is the captopril disulfide dimer and captopril-cysteine disulfide. Over 95% of the absorbed dose is eliminated in the urine within 24 hours; retention occurs in renal impairment.',
   'Após administração oral, a absorção é rápida, com picos sanguíneos a cerca de 1 hora. A presença de alimentos reduz a absorção em 30–40% — deve ser administrado 1 hora antes das refeições. A absorção mínima média é de ~75%; 25–30% do fármaco circulante liga-se às proteínas plasmáticas.',
   'After oral administration, absorption is rapid, with peak blood levels at about one hour. Food reduces absorption by 30–40% — it should be given one hour before meals. Average minimal absorption is approximately 75%; 25–30% of the circulating drug is bound to plasma proteins.',
   'A semivida aparente de eliminação do fármaco inalterado é provavelmente inferior a 2 horas (a semivida da radioatividade total no sangue é <3 horas). Na insuficiência renal há retenção do fármaco.',
   'The apparent elimination half-life of unchanged drug is probably less than 2 hours (the half-life of total blood radioactivity is <3 hours). Retention occurs in renal impairment.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Captopril, secção Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=563737c5-4d63-4957-8022-e3bc3112dfac',
   'DailyMed/FDA (NIH/NLM) — approved Captopril label, Clinical Pharmacology section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=563737c5-4d63-4957-8022-e3bc3112dfac'),

  ('colchicina',
   'Anti-inflamatório que interrompe a cascata inflamatória da crise de gota: liga-se à tubulina e inibe a mitose, a quimiotaxia dos neutrófilos e a adesão dos neutrófilos ao endotélio, bloqueando a libertação de mediadores inflamatórios. Não tem efeito analgésico direto nem reduz o ácido úrico.',
   'Anti-inflammatory that interrupts the inflammatory cascade of the gout flare: binds to tubulin and inhibits mitosis, neutrophil chemotaxis and neutrophil adhesion to the endothelium, blocking the release of inflammatory mediators. It has no direct analgesic effect nor does it lower uric acid.',
   'A colchicina liga-se à beta-tubulina formando complexos colchicina-tubulina que impedem a polimerização dos microtúbulos. Nos neutrófilos, inibe a quimiotaxia, a adesão e a produção de mediadores inflamatórios (incluindo o inflamassoma NLRP3), o que explica a eficácia na crise de gota e na febre familiar do Mediterrâneo.',
   'Colchicine binds to beta-tubulin forming colchicine-tubulin complexes that prevent microtubule polymerisation. In neutrophils, it inhibits chemotaxis, adhesion and the production of inflammatory mediators (including the NLRP3 inflammasome), explaining efficacy in gout flares and familial Mediterranean fever.',
   'A colchicina é desmetilada em dois metabolitos principais (2-O-desmetil e 3-O-desmetilcolchicina) e um menor (10-O-desmetil), via CYP3A4 (in vitro em microssomas hepáticos humanos). Os níveis plasmáticos dos metabolitos são mínimos (<5% do fármaco-mãe). É também substrato da glicoproteína-P.',
   'Colchicine is demethylated to two primary metabolites (2-O-demethyl and 3-O-demethylcolchicine) and one minor (10-O-demethyl), via CYP3A4 (in vitro in human liver microsomes). Plasma levels of the metabolites are minimal (<5% of parent drug). It is also a P-glycoprotein substrate.',
   'A colchicina é absorvida por via oral com Cmax média de 2,5 ng/mL em 1–2 horas (jejum); a biodisponibilidade absoluta é de ~45%. Os alimentos não alteram a velocidade mas diminuem a extensão da absorção em ~15%. O volume de distribuição é de ~5–8 L/kg e a ligação às proteínas séricas é baixa (39 ± 5%).',
   'Colchicine is absorbed orally with a mean Cmax of 2.5 ng/mL in 1–2 hours (fasting); absolute bioavailability is approximately 45%. Food does not change the rate but decreases the extent of absorption by ~15%. The volume of distribution is ~5–8 L/kg and serum protein binding is low (39 ± 5%).',
   'Após doses múltiplas (0,6 mg 2 vezes/dia), a semivida média de eliminação é de 26,6–31,2 horas em adultos jovens saudáveis. 40–65% da dose oral é recuperada inalterada na urina; há recirculação entero-hepática e excreção biliar. Não é removida por hemodiálise.',
   'After multiple doses (0.6 mg twice daily), the mean elimination half-life is 26.6–31.2 hours in healthy young adults. 40–65% of the oral dose is recovered unchanged in urine; there is enterohepatic recirculation and biliary excretion. It is not removed by haemodialysis.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Colchicina, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=72984aa2-6df9-4460-9926-399ffed30e36',
   'DailyMed/FDA (NIH/NLM) — approved Colchicine label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=72984aa2-6df9-4460-9926-399ffed30e36'),

  ('dabigatrano',
   'Anticoagulante oral de ação direta, inibidor reversível da trombina (fator IIa). Ao inibir a trombina, bloqueia a conversão do fibrinogénio em fibrina e a ativação dos fatores V, VIII e XIII e das plaquetas — o último passo da cascata da coagulação. Sem necessidade de monitorização de rotina da coagulação.',
   'Direct-acting oral anticoagulant, reversible inhibitor of thrombin (factor IIa). By inhibiting thrombin, it blocks the conversion of fibrinogen to fibrin and the activation of factors V, VIII and XIII and of platelets — the last step of the coagulation cascade. No routine coagulation monitoring is required.',
   'O dabigatrano liga-se ao sítio ativo da trombina (fator IIa), livre e ligada ao coágulo, impedindo a formação de fibrina e a ativação plaquetária dependente da trombina. A farmacodinâmica reflete-se no prolongamento do TTPa, do tempo de trombina e do ECT.',
   'Dabigatran binds to the active site of thrombin (factor IIa), both free and clot-bound, preventing fibrin formation and thrombin-dependent platelet activation. Pharmacodynamics are reflected in prolongation of aPTT, thrombin time and ECT.',
   'O dabigatrano etexilato é convertido em dabigatrano por hidrólise catalisada por esterases; o dabigatrano é depois conjugado em quatro acil-glucuronídeos ativos (cada um <10% do dabigatrano plasmático). Não é substrato, inibidor ou indutor do CYP450.',
   'Dabigatran etexilate is converted to dabigatran by esterase-catalysed hydrolysis; dabigatran is then conjugated to four active acyl glucuronides (each <10% of plasma dabigatran). It is not a substrate, inhibitor or inducer of CYP450.',
   'A biodisponibilidade absoluta do dabigatrano etexilato oral é de apenas 3–7%; a Cmax ocorre ~1 hora após a administração em jejum. Uma refeição rica em gordura atrasa a Cmax em ~2 horas sem afetar a biodisponibilidade. O dabigatrano liga-se às proteínas plasmáticas em ~35% e o volume de distribuição é de 50–70 L. As cápsulas não devem ser abertas (biodisponibilidade +75% sem a cápsula).',
   'Absolute bioavailability of oral dabigatran etexilate is only 3–7%; Cmax occurs ~1 hour after administration in the fasted state. A high-fat meal delays Cmax by ~2 hours without affecting bioavailability. Dabigatran is ~35% bound to plasma proteins and the volume of distribution is 50–70 L. Capsules must not be opened (bioavailability +75% without the capsule shell).',
   'A semivida do dabigatrano em adultos saudáveis é de 12–17 horas. A eliminação é predominantemente renal — a depuração renal representa ~80% da depuração total após administração intravenosa; a exposição aumenta com a gravidade da insuficiência renal.',
   'The half-life of dabigatran in healthy adults is 12–17 hours. Elimination is predominantly renal — renal clearance represents ~80% of total clearance after intravenous administration; exposure increases with the severity of renal impairment.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Dabigatrano etexilato, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3a8ec82a-c367-40dc-9302-e1896fcb05ea',
   'DailyMed/FDA (NIH/NLM) — approved Dabigatran etexilate label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3a8ec82a-c367-40dc-9302-e1896fcb05ea'),

  ('efavirenz',
   'Inibidor não nucleósido da transcriptase reversa (NNRTI) do VIH-1: liga-se diretamente à enzima transcriptase reversa, bloqueando a polimerização do ADN viral. Em associação com outros antirretrovirais reduz a carga viral e aumenta os CD4. Farmacocinética não linear com a dose; os efeitos neuropsiquiátricos estão relacionados com as concentrações plasmáticas.',
   'Non-nucleoside reverse transcriptase inhibitor (NNRTI) of HIV-1: binds directly to the reverse transcriptase enzyme, blocking viral DNA polymerisation. In combination with other antiretrovirals it reduces viral load and increases CD4. Non-linear pharmacokinetics with dose; neuropsychiatric effects are related to plasma concentrations.',
   'O efavirenz liga-se ao sítio alostérico da transcriptase reversa do VIH-1, induzindo uma alteração conformacional que inibe as atividades de polimerase ADN-dependente e ARN-dependente — não compete com os nucleósidos. Não é ativo contra o VIH-2.',
   'Efavirenz binds to an allosteric site of HIV-1 reverse transcriptase, inducing a conformational change that inhibits both DNA-dependent and RNA-dependent polymerase activities — it does not compete with nucleosides. It is not active against HIV-2.',
   'O efavirenz é metabolizado principalmente pelo sistema do citocromo P450 em metabolitos hidroxilados, depois glucuronidados (CYP3A e CYP2B6 são as principais isoenzimas). Induz o CYP (autoindução): doses múltiplas de 200–400 mg/dia durante 10 dias resultam em acumulação 22–42% menor e semivida terminal mais curta.',
   'Efavirenz is metabolised mainly by the cytochrome P450 system to hydroxylated metabolites, subsequently glucuronidated (CYP3A and CYP2B6 are the major isozymes). It induces CYP enzymes (autoinduction): multiple 200–400 mg/day doses for 10 days result in 22–42% lower accumulation and a shorter terminal half-life.',
   'Os picos plasmáticos ocorrem em 3–5 horas; o estado estacionário é atingido em 6–10 dias. Os alimentos (refeição rica em gordura) aumentam a AUC em 28% e a Cmax em 79% — tomar em jejum, preferencialmente à noite. A ligação às proteínas plasmáticas é muito elevada (~99,5–99,75%).',
   'Peak plasma concentrations occur in 3–5 hours; steady state is reached in 6–10 days. Food (high-fat meal) increases AUC by 28% and Cmax by 79% — take on an empty stomach, preferably at night. Plasma protein binding is very high (~99.5–99.75%).',
   'A semivida terminal é de 52–76 horas após doses únicas e de 40–55 horas após doses múltiplas. Menos de 1% é excretado inalterado na urina — o impacto da insuficiência renal na eliminação é mínimo.',
   'The terminal half-life is 52–76 hours after single doses and 40–55 hours after multiple doses. Less than 1% is excreted unchanged in urine — the impact of renal impairment on elimination is minimal.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Efavirenz, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=92603fa5-7a2c-4bfb-9a70-aadb4fba952c',
   'DailyMed/FDA (NIH/NLM) — approved Efavirenz label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=92603fa5-7a2c-4bfb-9a70-aadb4fba952c'),

  ('enalapril',
   'Inibidor da enzima de conversão da angiotensina (IECA); pró-fármaco hidrolisado a enalaprilato, o inibidor ativo. Reduz a formação de angiotensina II e aumenta a bradicinina, diminuindo a resistência vascular periférica e a pressão arterial, com redução da pré e pós-carga na insuficiência cardíaca. Na hipertensão, o início da ação antihipertensiva ocorre ~1 hora após a dose, com pico às 4–6 horas.',
   'Angiotensin-converting enzyme inhibitor (ACEI); prodrug hydrolysed to enalaprilat, the active inhibitor. Reduces angiotensin II formation and increases bradykinin, lowering peripheral vascular resistance and blood pressure, with reduced preload and afterload in heart failure. In hypertension, onset of antihypertensive activity occurs ~1 hour after the dose, with peak at 4–6 hours.',
   'O enalaprilato bloqueia a conversão da angiotensina I em angiotensina II (vasoconstritor potente) e reduz a degradação da bradicinina. O efeito na pressão arterial é semelhante em pé e deitado; a hipotensão ortostática sintomática é pouco frequente, exceto em doentes com depleção de volume.',
   'Enalaprilat blocks the conversion of angiotensin I to angiotensin II (potent vasoconstrictor) and reduces bradykinin degradation. The blood pressure effect is similar standing and supine; symptomatic orthostatic hypotension is infrequent, except in volume-depleted patients.',
   'O enalapril é hidrolisado a enalaprilato (inibidor mais potente; mal absorvido por via oral). O perfil sérico do enalaprilato apresenta uma fase terminal prolongada, aparentemente representando uma pequena fração ligada à ECA — a quantidade ligada não aumenta com a dose (local saturável). Não há evidência de outros metabolitos.',
   'Enalapril is hydrolysed to enalaprilat (more potent inhibitor; poorly absorbed orally). The serum profile of enalaprilat shows a prolonged terminal phase, apparently representing a small fraction bound to ACE — the amount bound does not increase with dose (saturable site). There is no evidence of other metabolites.',
   'Os picos séricos de enalapril ocorrem ~1 hora após a dose oral; a absorção é de ~60% (por recuperação urinária) e não é influenciada pelos alimentos. Os picos de enalaprilato ocorrem 3–4 horas após a dose. Cerca de 94% da dose é recuperada na urina e fezes como enalaprilato ou enalapril.',
   'Peak serum enalapril concentrations occur ~1 hour after an oral dose; absorption is ~60% (by urinary recovery) and is not influenced by food. Enalaprilat peaks occur 3–4 hours after the dose. Approximately 94% of the dose is recovered in urine and faeces as enalaprilat or enalapril.',
   'A semivida efetiva de acumulação do enalaprilato após doses múltiplas de enalapril é de ~11 horas. Com TFG ≤30 mL/min, os picos e vales de enalaprilato aumentam, o tempo até ao pico aumenta e a semivida efetiva prolonga-se; o enalaprilato é dialisável (62 mL/min).',
   'The effective half-life of enalaprilat accumulation after multiple doses of enalapril is ~11 hours. With GFR ≤30 mL/min, enalaprilat peaks and troughs increase, time to peak increases and the effective half-life is prolonged; enalaprilat is dialysable (62 mL/min).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Enalapril, secção Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0c829189-fba2-48f8-a23f-d5471a0345f6',
   'DailyMed/FDA (NIH/NLM) — approved Enalapril label, Clinical Pharmacology section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0c829189-fba2-48f8-a23f-d5471a0345f6'),

  ('enoxaparina',
   'Heparina de baixo peso molecular (HBPM) que potencia a antitrombina III, inibindo preferencialmente o fator Xa (atividade anti-Xa) e, em menor grau, o fator IIa (trombina). As atividades máximas anti-Xa e anti-IIa ocorrem 3–5 horas após a injeção subcutânea; a razão anti-Xa/anti-IIa é de ~3,6:1.',
   'Low molecular weight heparin (LMWH) that potentiates antithrombin III, inhibiting preferentially factor Xa (anti-Xa activity) and, to a lesser extent, factor IIa (thrombin). Peak anti-Xa and anti-IIa activities occur 3–5 hours after subcutaneous injection; the anti-Xa/anti-IIa ratio is ~3.6:1.',
   'A enoxaparina liga-se à antitrombina III, acelerando a inativação do fator Xa (principal efeito) e da trombina (fator IIa). A inibição preferencial do fator Xa, com menor ligação a proteínas plasmáticas que a heparina não fraccionada, confere farmacocinética mais previsível e menor risco de trombocitopenia.',
   'Enoxaparin binds to antithrombin III, accelerating the inactivation of factor Xa (main effect) and of thrombin (factor IIa). Preferential factor Xa inhibition, with less plasma protein binding than unfractionated heparin, confers more predictable pharmacokinetics and a lower risk of thrombocytopenia.',
   'A enoxaparina é metabolizada principalmente no fígado por dessulfatação e/ou despolimerização em espécies de menor peso molecular com potência biológica muito reduzida. A depuração renal dos fragmentos ativos representa ~10% da dose; a excreção renal total (ativa e não ativa) é ~40%.',
   'Enoxaparin is metabolised primarily in the liver by desulfation and/or depolymerisation to lower molecular weight species with much reduced biological potency. Renal clearance of active fragments represents ~10% of the dose; total renal excretion (active and inactive) is ~40% of the dose.',
   'A biodisponibilidade absoluta após injeção subcutânea (1,5 mg/kg) é de ~100%. Os picos de atividade anti-Xa ocorrem 3–5 horas após a injeção; o estado estacionário é atingido no 2.º dia (regimes de 40 mg/dia e 1,5 mg/kg/dia) ou no 4.º dia (1 mg/kg 2 vezes/dia). O volume de distribuição da atividade anti-Xa é de ~4,3 L.',
   'Absolute bioavailability after subcutaneous injection (1.5 mg/kg) is approximately 100%. Peak anti-Xa activity occurs 3–5 hours after injection; steady state is reached on day 2 (40 mg/day and 1.5 mg/kg/day regimens) or day 4 (1 mg/kg twice daily). The volume of distribution of anti-Xa activity is ~4.3 L.',
   'A semivida de eliminação baseada na atividade anti-Xa é de ~4,5 horas após dose subcutânea única, aumentando para ~7 horas após doses repetidas. Atividade anti-Xa significativa persiste no plasma ~12 horas após 40 mg uma vez ao dia.',
   'Elimination half-life based on anti-Xa activity is ~4.5 hours after a single subcutaneous dose, increasing to ~7 hours after repeated dosing. Significant anti-Xa activity persists in plasma for ~12 hours after a 40 mg once-daily dose.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Enoxaparina (LOVENOX), secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5017a927-2a24-4f27-89f9-27c805bf7d59',
   'DailyMed/FDA (NIH/NLM) — approved Enoxaparin (LOVENOX) label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5017a927-2a24-4f27-89f9-27c805bf7d59'),

  ('estreptomicina',
   'Antibiótico aminoglicosídeo bactericida que interfere com a síntese proteica bacteriana, com atividade contra micobactérias (incluindo M. tuberculosis) e vários gram-negativos. Após injeção intramuscular de 1 g, atinge-se um pico sérico de 25–50 mcg/mL em 1 hora, diminuindo para ~50% ao fim de 5–6 horas.',
   'Bactericidal aminoglycoside antibiotic that interferes with bacterial protein synthesis, active against mycobacteria (including M. tuberculosis) and several Gram-negatives. After intramuscular injection of 1 g, a peak serum level of 25–50 mcg/mL is reached within 1 hour, declining to ~50% after 5–6 hours.',
   'A estreptomicina liga-se à subunidade ribossomal 30S bacteriana, causando leitura incorreta do ARNm e incorporação de aminoácidos errados — a síntese proteica é interrompida e a bactéria morre. A ação é bactericida e dependente da concentração.',
   'Streptomycin binds to the bacterial 30S ribosomal subunit, causing mRNA misreading and incorporation of wrong amino acids — protein synthesis is interrupted and the bacterium dies. The action is bactericidal and concentration-dependent.',
   'A estreptomicina é excretada por filtração glomerular. Em doentes com função renal normal, entre 29% e 89% de uma dose única de 600 mg é excretada na urina em 24 horas. Qualquer redução da função glomerular resulta em diminuição da excreção e aumento dos níveis séricos e tecidulares.',
   'Streptomycin is excreted by glomerular filtration. In patients with normal kidney function, between 29% and 89% of a single 600 mg dose is excreted in the urine within 24 hours. Any reduction of glomerular function results in decreased excretion and a concurrent rise in serum and tissue levels.',
   'Após injeção intramuscular, a absorção é rápida e completa, com pico sérico de 25–50 mcg/mL 1 hora após 1 g. Concentrações apreciáveis são encontradas em todos os tecidos exceto o cérebro; atravessa a placenta (níveis no sangue do cordão semelhantes aos maternos) e pequenas quantidades passam para o leite.',
   'After intramuscular injection, absorption is rapid and complete, with a peak serum level of 25–50 mcg/mL 1 hour after 1 g. Appreciable concentrations are found in all tissues except the brain; it crosses the placenta (cord blood levels similar to maternal) and small amounts pass into milk.',
   'A semivida sérica efetiva é de ~5–6 horas (o pico de 25–50 mcg/mL diminui para cerca de metade ao fim de 5–6 horas); a eliminação prolonga-se na insuficiência renal.',
   'The effective serum half-life is ~5–6 hours (the 25–50 mcg/mL peak declines to about half after 5–6 hours); elimination is prolonged in renal impairment.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Estreptomicina, secção Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=abd1f64e-4283-4370-aae8-3666316aa36e',
   'DailyMed/FDA (NIH/NLM) — approved Streptomycin label, Clinical Pharmacology section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=abd1f64e-4283-4370-aae8-3666316aa36e'),

  ('fenobarbital',
   'Barbitúrico de ação longa com propriedades anticonvulsivantes, sedativas e hipnóticas. Como anticonvulsivante, eleva o limiar convulsivo e limita a propagação da atividade convulsiva; como sedativo, produz sedação em doses inferiores às hipnóticas. O início de ação oral é ≥1 hora e a duração de ação é de 10–12 horas.',
   'Long-acting barbiturate with anticonvulsant, sedative and hypnotic properties. As an anticonvulsant, it raises the seizure threshold and limits the spread of seizure activity; as a sedative, it produces sedation at doses below the hypnotic ones. Oral onset of action is ≥1 hour and the duration of action is 10–12 hours.',
   'Os barbitúricos potencializam a inibição GABAérgica: ligam-se ao complexo recetor GABA-A, prolongando a duração da abertura do canal de cloro e hiperpolarizando o neurónio. Em doses mais altas deprimem também a neurotransmissão excitatória (glutamatérgica).',
   'Barbiturates potentiate GABAergic inhibition: they bind to the GABA-A receptor complex, prolonging the duration of chloride channel opening and hyperpolarising the neurone. At higher doses they also depress excitatory (glutamatergic) neurotransmission.',
   'Os barbitúricos são metabolizados principalmente pelo sistema enzimático microssómico hepático; os produtos metabólicos são excretados na urina e, menos frequentemente, nas fezes. O fenobarbital é um indutor enzimático hepático potente — acelera o seu próprio metabolismo e o de muitos outros fármacos.',
   'Barbiturates are metabolised primarily by the hepatic microsomal enzyme system; the metabolic products are excreted in the urine and, less commonly, in the faeces. Phenobarbital is a potent hepatic enzyme inducer — it accelerates its own metabolism and that of many other drugs.',
   'Aproximadamente 25–50% de uma dose de fenobarbital é eliminada inalterada na urina — a excreção de barbitúrico não metabolizado distingue a categoria de ação longa das restantes, quase totalmente metabolizadas. Os ácidos fracos como os barbitúricos são absorvidos em graus variáveis; os sais são absorvidos mais rapidamente e a absorção aumenta em jejum.',
   'Approximately 25–50% of a dose of phenobarbital is eliminated unchanged in the urine — excretion of unmetabolised barbiturate distinguishes the long-acting category from others, which are almost entirely metabolised. Weak acids such as barbiturates are absorbed to varying degrees; the salts are absorbed more rapidly and absorption is increased on an empty stomach.',
   'A semivida plasmática do fenobarbital em adultos varia entre 53 e 118 horas, com uma média de 79 horas; em crianças e recém-nascidos (<48 horas) varia entre 60 e 180 horas (média 110 horas). É o barbitúrico de menor solubilidade lipídica, menor ligação proteica e maior duração de ação.',
   'The plasma half-life of phenobarbital in adults ranges between 53 and 118 hours, with a mean of 79 hours; in children and newborns (<48 hours) it ranges between 60 and 180 hours (mean 110 hours). It is the barbiturate with the lowest lipid solubility, lowest protein binding and longest duration of action.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Fenobarbital, secção Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fa09b4f2-edb0-4594-a2d2-b16f7b9686b4',
   'DailyMed/FDA (NIH/NLM) — approved Phenobarbital label, Clinical Pharmacology section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fa09b4f2-edb0-4594-a2d2-b16f7b9686b4'),

  ('levofloxacina',
   'Fluoroquinolona bactericida de largo espetro que inibe a ADN-girase (topoisomerase II) e a topoisomerase IV bacterianas, bloqueando a replicação, transcrição e reparação do ADN. Ativa contra gram-negativos (incluindo Pseudomonas aeruginosa) e gram-positivos; farmacocinética linear e previsível por via oral e intravenosa.',
   'Broad-spectrum bactericidal fluoroquinolone that inhibits bacterial DNA gyrase (topoisomerase II) and topoisomerase IV, blocking DNA replication, transcription and repair. Active against Gram-negatives (including Pseudomonas aeruginosa) and Gram-positives; linear and predictable pharmacokinetics by oral and intravenous routes.',
   'A levofloxacina liga-se aos complexos ADN-enzima das topoisomerases bacterianas (ADN-girase e topoisomerase IV), estabilizando o complexo de clivagem e impedindo a religação do ADN — a replicação bacteriana é interrompida. O alvo principal difere entre gram-negativos (girase) e gram-positivos (topoisomerase IV).',
   'Levofloxacin binds to the DNA-enzyme complexes of bacterial topoisomerases (DNA gyrase and topoisomerase IV), stabilising the cleavage complex and preventing DNA religation — bacterial replication is interrupted. The primary target differs between Gram-negatives (gyrase) and Gram-positives (topoisomerase IV).',
   'A levofloxacina é minimamente metabolizada (~5%): sofre pouca biotransformação e é excretada principalmente inalterada na urina por filtração glomerular e secreção tubular. A excreção renal é responsável pela maior parte da eliminação — a dose deve ser ajustada na insuficiência renal.',
   'Levofloxacin is minimally metabolised (~5%): it undergoes little biotransformation and is excreted mainly unchanged in urine by glomerular filtration and tubular secretion. Renal excretion accounts for most elimination — the dose must be adjusted in renal impairment.',
   'A levofloxacina é rápida e essencialmente completamente absorvida por via oral, com biodisponibilidade absoluta de ~99% (comprimidos de 500 e 750 mg). Os picos plasmáticos ocorrem 1–2 horas após a dose; os alimentos atrasam o pico ~1 hora e diminuem-no ~14% (sem relevância clínica). O volume de distribuição é de 74–112 L.',
   'Levofloxacin is rapidly and essentially completely absorbed orally, with an absolute bioavailability of ~99% (500 mg and 750 mg tablets). Peak plasma concentrations occur 1–2 hours after dosing; food delays the peak ~1 hour and decreases it ~14% (without clinical relevance). The volume of distribution is 74–112 L.',
   'A semivida de eliminação é de ~6,3–8,8 horas em doentes com função renal normal (mais longa na insuficiência renal: 27 horas com TFG 20–49 mL/min; 35 horas com TFG <20 mL/min). O estado estacionário é atingido em 48 horas com a toma diária.',
   'The elimination half-life is ~6.3–8.8 hours in patients with normal renal function (longer in renal impairment: 27 hours with CrCl 20–49 mL/min; 35 hours with CrCl <20 mL/min). Steady state is reached within 48 hours of daily dosing.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Levofloxacina, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=857f256c-88ac-4f73-9815-c2724edf2f1e',
   'DailyMed/FDA (NIH/NLM) — approved Levofloxacin label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=857f256c-88ac-4f73-9815-c2724edf2f1e'),

  ('linezolida',
   'Oxazolidinona bacteriostática que inibe a síntese proteica bacteriana, com atividade contra bactérias gram-positivas, incluindo Staphylococcus aureus resistente à meticilina (MRSA), estafilococos coagulase-negativos, estreptococos e enterococos resistentes à vancomicina (VRE).',
   'Bacteriostatic oxazolidinone that inhibits bacterial protein synthesis, active against Gram-positive bacteria, including methicillin-resistant Staphylococcus aureus (MRSA), coagulase-negative staphylococci, streptococci and vancomycin-resistant enterococci (VRE).',
   'A linezolida liga-se à subunidade ribossomal 50S bacteriana (sítio P), impedindo a formação do complexo de iniciação 70S — bloqueia a síntese proteica num passo anterior ao dos macrólidos e aminoglicosídeos. Este mecanismo distinto explica a ausência de resistência cruzada com outras classes.',
   'Linezolid binds to the bacterial 50S ribosomal subunit (P site), preventing the formation of the 70S initiation complex — blocking protein synthesis at a step earlier than macrolides and aminoglycosides. This distinct mechanism explains the lack of cross-resistance with other classes.',
   'A linezolida é metabolizada principalmente por oxidação do anel morfolínico, originando dois metabolitos inativos (metabolito A, aminoetoxiacético, e metabolito B, hidroxietilglicina). A metabolização pelo CYP450 é mínima; a depuração não renal representa ~65% da depuração total.',
   'Linezolid is metabolised primarily by oxidation of the morpholine ring, producing two inactive metabolites (metabolite A, aminoethoxyacetic acid, and metabolite B, hydroxyethyl glycine). CYP450 metabolism is minimal; nonrenal clearance accounts for ~65% of total clearance.',
   'A linezolida é extensamente absorvida após dose oral, com biodisponibilidade absoluta de ~100% e picos plasmáticos 1–2 horas após a dose. Os alimentos atrasam o pico (1,5 → 2,2 horas) e diminuem a Cmax ~17%, sem alterar a exposição total. A ligação às proteínas plasmáticas é de ~31% e o volume de distribuição no estado estacionário é de 40–50 L.',
   'Linezolid is extensively absorbed after oral dosing, with an absolute bioavailability of ~100% and peak plasma concentrations 1–2 hours after dosing. Food delays the peak (1.5 → 2.2 hours) and decreases Cmax ~17%, without changing total exposure. Plasma protein binding is ~31% and the steady-state volume of distribution is 40–50 L.',
   'A semivida de eliminação é de ~4,3–5,4 horas (5,2 horas para 400 mg; 4,26–5,4 horas para 600 mg). No estado estacionário, ~30% da dose aparece na urina como linezolida, 40% como metabolito B e 10% como metabolito A; praticamente não aparece inalterada nas fezes.',
   'The elimination half-life is ~4.3–5.4 hours (5.2 hours for 400 mg; 4.26–5.4 hours for 600 mg). At steady state, ~30% of the dose appears in urine as linezolid, 40% as metabolite B and 10% as metabolite A; virtually none appears unchanged in faeces.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Linezolida, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=90dd8c13-c428-4472-91e5-5b1fcdc4fce3',
   'DailyMed/FDA (NIH/NLM) — approved Linezolid label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=90dd8c13-c428-4472-91e5-5b1fcdc4fce3'),

  ('metotrexato',
   'Antagonista do ácido fólico com efeitos antiproliferativo e imunomodulador: inibe a di-hidrofolato redutase, bloqueando a síntese de timidilato e de purinas, essenciais para a replicação do ADN e a proliferação celular. Em doses baixas semanais (doenças inflamatórias) o efeito anti-inflamatório relaciona-se também com o aumento da adenosina extracelular.',
   'Folate antagonist with antiproliferative and immunomodulatory effects: inhibits dihydrofolate reductase, blocking thymidylate and purine synthesis, essential for DNA replication and cell proliferation. At low weekly doses (inflammatory diseases) the anti-inflammatory effect is also related to increased extracellular adenosine.',
   'O metotrexato liga-se e inibe competitivamente a di-hidrofolato redutase (DHFR), esgotando o folato reduzido intracelular e bloqueando a síntese de timidilato e purinas. A leucovorina (ácido folínico) contorna este bloqueio — daí o seu uso como resgate após doses altas.',
   'Methotrexate binds to and competitively inhibits dihydrofolate reductase (DHFR), depleting intracellular reduced folate and blocking thymidylate and purine synthesis. Leucovorin (folinic acid) bypasses this block — hence its use as rescue after high doses.',
   'O metotrexato é parcialmente metabolizado pela flora intestinal após administração oral e, principalmente, metabolizado no fígado e intracelularmente em formas poliglutamadas ativas (que podem reconverter-se em metotrexato). Sofre também metabolismo menor em 7-hidroximetotrexato ativo. A excreção é predominantemente renal (filtração glomerular e secreção tubular ativa); a excreção biliar representa ≤10%.',
   'Methotrexate is partially metabolised by intestinal flora after oral administration and, mainly, metabolised in the liver and intracellularly to active polyglutamated forms (which can be converted back to methotrexate). It also undergoes minor metabolism to active 7-hydroxymethotrexate. Excretion is predominantly renal (glomerular filtration and active tubular secretion); biliary excretion accounts for ≤10%.',
   'Em doses ≤30 mg/m2, a biodisponibilidade média é de ~60%, com picos plasmáticos 0,75–6 horas após administração oral; os alimentos atrasam a absorção e reduzem o pico. O metotrexato liga-se às proteínas séricas em ~50% e não penetra a barreira hematoencefálica nas concentrações recomendadas. Pode haver recirculação entero-hepática.',
   'At doses ≤30 mg/m2, mean bioavailability is ~60%, with peak plasma concentrations 0.75–6 hours after oral administration; food delays absorption and reduces the peak. Methotrexate is ~50% protein bound and does not penetrate the blood-brain barrier at recommended concentrations. Enterohepatic recirculation may occur.',
   'A semivida de eliminação é de ~3–10 horas. Pequenas quantidades de poliglutamatos podem permanecer nos tecidos durante períodos prolongados — a retenção e a ação prolongada destes metabolitos ativos variam entre células, tecidos e tumores. A semivida aumenta com a gravidade da insuficiência renal.',
   'The elimination half-life is ~3–10 hours. Small amounts of polyglutamates may remain in tissues for extended periods — the retention and prolonged action of these active metabolites vary among cells, tissues and tumours. The half-life increases with the severity of renal impairment.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Metotrexato, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=04a95db9-a124-4b97-bd71-1c37a6b3b0c8',
   'DailyMed/FDA (NIH/NLM) — approved Methotrexate label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=04a95db9-a124-4b97-bd71-1c37a6b3b0c8'),

  ('pseudoefedrina',
   'Simpaticomimético de ação periférica (agonista alfa-1 adrenérgico predominante) que contrai os vasos da mucosa nasal e dos seios perinasais, reduzindo a congestão e o edema. O alívio da congestão nasal é o efeito terapêutico estabelecido; a ação central (estimulante) é mínima em comparação com a efedrina.',
   'Peripheral sympathomimetic (predominant alpha-1 adrenergic agonist) that constricts the vessels of the nasal and sinus mucosa, reducing congestion and oedema. Relief of nasal congestion is the established therapeutic effect; central (stimulant) action is minimal compared with ephedrine.',
   'A pseudoefedrina ativa os recetores alfa-1 adrenérgicos da mucosa respiratória, provocando vasoconstrição arteriolar, diminuição do fluxo sanguíneo e do edema da mucosa. Em doses terapêuticas orais os efeitos beta e centrais são pouco relevantes.',
   'Pseudoephedrine activates alpha-1 adrenergic receptors of the respiratory mucosa, causing arteriolar vasoconstriction, decreased blood flow and mucosal oedema. At therapeutic oral doses the beta and central effects are of little relevance.',
   'A pseudoefedrina é metabolizada em pequena extensão no fígado (N-desmetilação); é excretada predominantemente inalterada na urina (43–96% da dose), por filtração glomerular e secreção tubular. A excreção renal depende fortemente do pH urinário — a alcalinização aumenta a reabsorção tubular e prolonga a semivida (de 1,9 para até 21 horas).',
   'Pseudoephedrine is metabolised to a small extent in the liver (N-demethylation); it is excreted predominantly unchanged in the urine (43–96% of the dose), by glomerular filtration and tubular secretion. Renal excretion depends strongly on urinary pH — alkalinisation increases tubular reabsorption and prolongs the half-life (from 1.9 to up to 21 hours).',
   'A pseudoefedrina é bem absorvida por via oral, com picos plasmáticos 1–2 horas após a dose; a biodisponibilidade oral é de ~90% (os comprimidos de libertação prolongada têm picos mais tardios). A ligação às proteínas plasmáticas é mínima.',
   'Pseudoephedrine is well absorbed orally, with plasma peaks 1–2 hours after the dose; oral bioavailability is ~90% (extended-release tablets have later peaks). Plasma protein binding is minimal.',
   'A semivida de eliminação em adultos é de ~4–8 horas (média ~5,4 horas), dependente do pH urinário (1,9 horas com urina ácida até ~21 horas com urina alcalina); em crianças é de ~3,1 horas.',
   'The elimination half-life in adults is ~4–8 hours (mean ~5.4 hours), dependent on urinary pH (1.9 hours with acid urine up to ~21 hours with alkaline urine); in children it is ~3.1 hours.',
   'Rótulo OTC DailyMed (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8c4c786c-2b0f-4a23-a87d-effbcfe0c857 — farmacocinética: PubMed PMID 7507589 (Kanfer et al., Pharmacokinetics of oral decongestants, 1993); PMID 7438686 (Brater et al., Renal excretion of pseudoephedrine, 1980)',
   'OTC DailyMed label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8c4c786c-2b0f-4a23-a87d-effbcfe0c857 — pharmacokinetics: PubMed PMID 7507589 (Kanfer et al., Pharmacokinetics of oral decongestants, 1993); PMID 7438686 (Brater et al., Renal excretion of pseudoephedrine, 1980)'),

  ('rifabutina',
   'Antibiótico rifamicina (derivado da rifamicina-S) bactericida que inibe a ARN-polimerase dependente de ADN bacteriana, bloqueando a transcrição. Ativo contra micobactérias atípicas (Mycobacterium avium complex), M. tuberculosis e vários gram-positivos e gram-negativos. Indutor enzimático mais fraco que a rifampicina.',
   'Bactericidal rifamycin antibiotic (rifamycin-S derivative) that inhibits bacterial DNA-dependent RNA polymerase, blocking transcription. Active against atypical mycobacteria (Mycobacterium avium complex), M. tuberculosis and various Gram-positives and Gram-negatives. Weaker enzyme inducer than rifampicin.',
   'A rifabutina liga-se à subunidade beta da ARN-polimerase dependente de ADN bacteriana, impedindo a iniciação da transcrição do ARN. A resistência resulta de mutações na polimerase; a rifabutina mantém atividade contra algumas estirpes resistentes à rifampicina.',
   'Rifabutin binds to the beta subunit of bacterial DNA-dependent RNA polymerase, preventing the initiation of RNA transcription. Resistance results from polymerase mutations; rifabutin retains activity against some rifampicin-resistant strains.',
   'A rifabutina é extensamente metabolizada no fígado em cinco metabolitos; os predominantes são o 25-O-desacetil (com atividade igual à do fármaco-mãe, contribuindo até 10% da atividade antimicrobiana) e o 31-hidroxi. O metabolismo é induzível (autoindução e indução do CYP3A).',
   'Rifabutin is extensively metabolised in the liver to five metabolites; the predominant ones are 25-O-desacetyl (with activity equal to the parent drug, contributing up to 10% of antimicrobial activity) and 31-hydroxy. Metabolism is inducible (autoinduction and CYP3A induction).',
   'Após dose oral única de 300 mg, a rifabutina é prontamente absorvida, com picos plasmáticos médios de 375 ng/mL em ~3,3 horas; a biodisponibilidade absoluta é de ~20% (≥53% da dose é absorvida). Refeições ricas em gordura atrasam a absorção sem reduzir a extensão. A ligação às proteínas plasmáticas é de ~85%.',
   'After a single oral 300 mg dose, rifabutin is readily absorbed, with mean peak plasma levels of 375 ng/mL in ~3.3 hours; absolute bioavailability is ~20% (at least 53% of the dose is absorbed). High-fat meals slow absorption without reducing the extent. Plasma protein binding is ~85%.',
   'A rifabutina é eliminada lentamente do plasma, com semivida terminal média de ~45 horas (variação 16–69 horas), presumivelmente por eliminação limitada pela distribuição. ~53% da dose oral é excretada na urina (principalmente como metabolitos) e ~30% nas fezes.',
   'Rifabutin is slowly eliminated from plasma, with a mean terminal half-life of ~45 hours (range 16–69 hours), presumably because of distribution-limited elimination. ~53% of the oral dose is excreted in the urine (mainly as metabolites) and ~30% in the faeces.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Rifabutina, secção Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c2026b67-4755-4236-96b6-a6b5e7399707',
   'DailyMed/FDA (NIH/NLM) — approved Rifabutin label, Clinical Pharmacology section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c2026b67-4755-4236-96b6-a6b5e7399707'),

  ('rivaroxabano',
   'Anticoagulante oral de ação direta que inibe seletiva e reversivelmente o fator Xa, reduzindo a geração de trombina e a formação do trombo. A inibição do fator Xa prolonga o tempo de protrombina (TP) e o TTPa de forma dose-dependente; sem necessidade de monitorização de rotina.',
   'Direct-acting oral anticoagulant that selectively and reversibly inhibits factor Xa, reducing thrombin generation and thrombus formation. Factor Xa inhibition prolongs prothrombin time (PT) and aPTT dose-dependently; no routine monitoring required.',
   'O rivaroxabano liga-se ao sítio ativo do fator Xa, livre e ligado ao complexo protrombinase, inibindo a conversão da protrombina em trombina. Não inibe diretamente a trombina nem afeta a agregação plaquetária.',
   'Rivaroxaban binds to the active site of factor Xa, both free and within the prothrombinase complex, inhibiting the conversion of prothrombin to thrombin. It does not directly inhibit thrombin nor affect platelet aggregation.',
   'Cerca de 51% da dose oral é recuperada como metabolitos inativos na urina (30%) e fezes (21%). A degradação oxidativa pelo CYP3A4/5 e CYP2J2 e a hidrólise são os principais locais de biotransformação; não há metabolitos ativos circulantes major.',
   'Approximately 51% of the oral dose is recovered as inactive metabolites in urine (30%) and faeces (21%). Oxidative degradation by CYP3A4/5 and CYP2J2 and hydrolysis are the major sites of biotransformation; there are no major active circulating metabolites.',
   'A biodisponibilidade absoluta é dose-dependente: 80–100% para 2,5 mg e ~66% para 20 mg em jejum (os alimentos aumentam a absorção das doses 15/20 mg). Os picos ocorrem 2–4 horas após a toma; a ligação às proteínas plasmáticas é de 92–95% e o volume de distribuição no estado estacionário é de ~50 L.',
   'Absolute bioavailability is dose-dependent: 80–100% for 2.5 mg and ~66% for 20 mg fasted (food increases absorption of the 15/20 mg doses). Peaks occur 2–4 hours after intake; plasma protein binding is 92–95% and the steady-state volume of distribution is ~50 L.',
   'A semivida terminal de eliminação é de 5–9 horas em adultos jovens saudáveis (20–45 anos) e de 11–13 horas em idosos (60–76 anos). A depuração sistémica é de ~10 L/hora; ~36% da dose é recuperada inalterada na urina (secretada ativamente) e 7% nas fezes.',
   'The terminal elimination half-life is 5–9 hours in healthy young adults (20–45 years) and 11–13 hours in the elderly (60–76 years). Systemic clearance is ~10 L/hour; ~36% of the dose is recovered unchanged in urine (actively secreted) and 7% in faeces.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Rivaroxabano, secção 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=481b7802-5093-43e7-bbd9-1532197eb6e6',
   'DailyMed/FDA (NIH/NLM) — approved Rivaroxaban label, section 12 Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=481b7802-5093-43e7-bbd9-1532197eb6e6'),

  ('salbutamol',
   'Agonista beta-2 adrenérgico seletivo de curta duração (SABA): relaxa o músculo liso brônquico de toda a árvore respiratória, da traqueia aos bronquíolos terminais, atuando como antagonista funcional independentemente do espasmogénio. O início de ação é de ~6 minutos, com pico aos 50–55 minutos e duração de ~3 horas (até 6 horas nalguns doentes).',
   'Selective short-acting beta-2 adrenergic agonist (SABA): relaxes bronchial smooth muscle of the whole airway tree, from the trachea to the terminal bronchioles, acting as a functional antagonist regardless of the spasmogen. Onset of action is ~6 minutes, with peak at 50–55 minutes and duration of ~3 hours (up to 6 hours in some patients).',
   'A ativação dos recetores beta-2 do músculo liso brônquico ativa a adenilciclase, aumentando o AMPc intracelular; o AMPc ativa a proteína cinase A, que inibe a fosforilação da miosina e reduz o cálcio intracelular, resultando em relaxamento. O aumento do AMPc associa-se também à inibição da libertação de mediadores dos mastócitos.',
   'Activation of beta-2 receptors on bronchial smooth muscle activates adenyl cyclase, increasing intracellular cAMP; cAMP activates protein kinase A, which inhibits myosin phosphorylation and lowers intracellular calcium, resulting in relaxation. Increased cAMP is also associated with inhibition of mast cell mediator release.',
   'O salbutamol é extensamente metabolizado no fígado por conjugação (sulfatação) a um metabolito inativo (sulfato de salbutamol); a eliminação é mista, renal e biliar. A biodisponibilidade oral é de ~50% (metabolismo de primeira passagem); após inalação, a fração que atinge a circulação é pequena.',
   'Salbutamol is extensively metabolised in the liver by conjugation (sulphation) to an inactive metabolite (salbutamol sulphate); elimination is mixed, renal and biliary. Oral bioavailability is ~50% (first-pass metabolism); after inhalation, the fraction reaching the circulation is small.',
   'O salbutamol é rápida e bem absorvido por via oral, com biodisponibilidade absoluta de ~44–50% nas preparações orais; após inalação, a absorção sistémica é rápida (níveis plasmáticos baixos). O inalador MDI tem início de ação em ~6 minutos e pico de efeito aos 50–55 minutos.',
   'Salbutamol is rapidly and well absorbed orally, with an absolute bioavailability of ~44–50% for oral preparations; after inhalation, systemic absorption is rapid (low plasma levels). The MDI inhaler has an onset of action of ~6 minutes and peak effect at 50–55 minutes.',
   'A semivida de eliminação do salbutamol é de ~3,8–5 horas (média ~5,7 horas para o fármaco e ~4,1 horas para o conjugado sulfato após dose oral); após inalação, o efeito broncodilatador dura ~3 horas (até 6 horas nalguns doentes).',
   'The elimination half-life of salbutamol is ~3.8–5 hours (mean ~5.7 hours for the drug and ~4.1 hours for the sulphate conjugate after an oral dose); after inhalation, the bronchodilator effect lasts ~3 hours (up to 6 hours in some patients).',
   'Rótulo DailyMed (MDI/HFA): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=583c6408-45cc-9121-e063-6294a90afcc4 — farmacocinética: PubMed PMID 3653233 (Pharmacokinetics and absolute bioavailability of salbutamol, 1987); PMID 1457264 (Determination of the relative bioavailability of salbutamol, 1992)',
   'DailyMed label (MDI/HFA): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=583c6408-45cc-9121-e063-6294a90afcc4 — pharmacokinetics: PubMed PMID 3653233 (Pharmacokinetics and absolute bioavailability of salbutamol, 1987); PMID 1457264 (Determination of the relative bioavailability of salbutamol, 1992)'),

  ('sucralfato',
   'Agente citoprotetor que atua localmente na mucosa gastrointestinal: forma um complexo aderente com o exsudado proteico da úlcera, criando uma barreira que impede a difusão dos iões de hidrogénio e protege a mucosa do ácido, da pepsina e dos sais biliares. Acelera a cicatrização da úlcera duodenal.',
   'Cytoprotective agent acting locally on the gastrointestinal mucosa: forms an adherent complex with the proteinaceous exudate of the ulcer, creating a barrier that prevents hydrogen ion diffusion and protects the mucosa from acid, pepsin and bile salts. Accelerates duodenal ulcer healing.',
   'Em condições ácidas, o sucralfato polimeriza e liga-se eletrostaticamente às proteínas carregadas positivamente do exsudado da úlcera (formação de um gel aderente); a película resultante é uma barreira física à difusão de iões de hidrogénio e adsorve a pepsina e os sais biliares.',
   'Under acidic conditions, sucralfate polymerises and binds electrostatically to the positively charged proteins of the ulcer exudate (formation of an adherent gel); the resulting film is a physical barrier to hydrogen ion diffusion and adsorbs pepsin and bile salts.',
   'O sucralfato é apenas minimamente absorvido; pequenas quantidades do dissacarídeo sulfatado absorvido são excretadas principalmente na urina. A maior parte da dose permanece no trato gastrointestinal e é eliminada nas fezes.',
   'Sucralfate is only minimally absorbed; small amounts of the absorbed sulphated disaccharide are excreted primarily in the urine. Most of the dose remains in the gastrointestinal tract and is eliminated in the faeces.',
   'A absorção gastrointestinal é mínima (<5%), pelo que a ação é essencialmente local; a formação do gel aderente requer pH ácido — administrar em jejum (1 hora antes das refeições e ao deitar), quando o pH gástrico é mais baixo.',
   'Gastrointestinal absorption is minimal (<5%), so the action is essentially local; adherent gel formation requires acidic pH — administer on an empty stomach (1 hour before meals and at bedtime), when gastric pH is lowest.',
   'A semivida não é clinicamente relevante dado o efeito local e a absorção mínima; o fármaco permanece no trato gastrointestinal até ser eliminado nas fezes. Por interação local (adsorção), reduz a absorção de vários fármacos administrados em simultâneo.',
   'Half-life is not clinically relevant given the local effect and minimal absorption; the drug remains in the gastrointestinal tract until eliminated in the faeces. By local interaction (adsorption), it reduces the absorption of several drugs administered at the same time.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Sucralfato, secção Clinical Pharmacology: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1e781cc0-24ec-4028-8262-dcef9873ea1f',
   'DailyMed/FDA (NIH/NLM) — approved Sucralfate label, Clinical Pharmacology section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1e781cc0-24ec-4028-8262-dcef9873ea1f'),

  ('dextrometorfano',
   'Antitússico de ação central: eleva o limiar da tosse no centro da tosse do tronco cerebral (núcleo do trato solitário), suprimindo a tosse seca sem efeito analgésico ou sedativo significativo nas doses terapêuticas. Derivado do levorfanol, sem afinidade relevante para os recetores opioides nas doses habituais.',
   'Centrally acting antitussive: raises the cough threshold in the brainstem cough centre (nucleus tractus solitarius), suppressing dry cough without significant analgesic or sedative effect at therapeutic doses. A levorphanol derivative without relevant opioid receptor affinity at usual doses.',
   'O dextrometorfano atua sobre o centro da tosse no tronco cerebral; é também antagonista dos recetores NMDA em doses altas (propriedades dissociativas que explicam o potencial de abuso). O seu metabolito ativo dextrorfano contribui para o efeito antitússico.',
   'Dextromethorphan acts on the cough centre in the brainstem; it is also an NMDA receptor antagonist at high doses (dissociative properties explaining the abuse potential). Its active metabolite dextrorphan contributes to the antitussive effect.',
   'O dextrometorfano é metabolizado principalmente pelo CYP2D6 em dextrorfano (O-desmetilação), o metabolito ativo, com vias menores pelo CYP3A4/5 (N-desmetilação). O polimorfismo do CYP2D6 influencia fortemente a exposição: nos metabolizadores lentos, a semivida e os níveis aumentam muito; a quinidina e os ISRS inibem o CYP2D6.',
   'Dextromethorphan is metabolised mainly by CYP2D6 to dextrorphan (O-demethylation), the active metabolite, with minor pathways by CYP3A4/5 (N-demethylation). CYP2D6 polymorphism strongly influences exposure: in poor metabolisers, half-life and levels greatly increase; quinidine and SSRIs inhibit CYP2D6.',
   'O dextrometorfano é bem absorvido por via oral, com picos plasmáticos 1–2 horas após a dose; sofre metabolismo de primeira passagem hepática. A biodisponibilidade oral é variável (~11–70%) dependendo do fenótipo do CYP2D6; os comprimidos de libertação prolongada têm picos mais tardios.',
   'Dextromethorphan is well absorbed orally, with plasma peaks 1–2 hours after the dose; it undergoes hepatic first-pass metabolism. Oral bioavailability is variable (~11–70%) depending on the CYP2D6 phenotype; extended-release formulations have later peaks.',
   'A semivida de eliminação é de ~2–4 horas nos metabolizadores extensos, de ~5,6 horas quando o CYP2D6 é inibido (ex.: quinidina) e de ~19 horas nos metabolizadores lentos (CYP2D6).',
   'The elimination half-life is ~2–4 hours in extensive metabolisers, ~5.6 hours when CYP2D6 is inhibited (e.g. quinidine) and ~19 hours in poor metabolisers (CYP2D6).',
   'Rótulo OTC DailyMed (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0d99237c-0b52-0af6-e063-6394a90aba14 — farmacocinética: PubMed PMID 7593709 (Influence of CYP2D6 phenotype and quinidine inhibition, 1995); PMID 8841152 (The influence of CYP2D6 polymorphism and quinidine, 1996)',
   'OTC DailyMed label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0d99237c-0b52-0af6-e063-6394a90aba14 — pharmacokinetics: PubMed PMID 7593709 (Influence of CYP2D6 phenotype and quinidine inhibition, 1995); PMID 8841152 (The influence of CYP2D6 polymorphism and quinidine, 1996)'),

  ('difenidramina',
   'Anti-histamínico H1 de primeira geração com marcado efeito sedativo e propriedades antimuscarínicas, antieméticas e antipruriginosas. Bloqueia os efeitos da histamina na mucosa respiratória e na pele (alívio de espirros, corrimento nasal, comichão) e, por ação central, produz sonolência — usada também como hipnótico ocasional.',
   'First-generation H1 antihistamine with marked sedative effect and antimuscarinic, antiemetic and antipruritic properties. Blocks histamine effects on the respiratory mucosa and skin (relief of sneezing, runny nose, itching) and, by central action, produces drowsiness — also used as an occasional hypnotic.',
   'A difenidramina antagoniza competitivamente os recetores H1 da histamina, bloqueando os efeitos vasodilatadores e de permeabilidade capilar da histamina. Ao contrário dos anti-histamínicos de segunda geração, atravessa a barreira hematoencefálica — o bloqueio dos recetores H1 centrais explica a sedação marcada.',
   'Diphenhydramine competitively antagonises histamine H1 receptors, blocking the vasodilator and capillary permeability effects of histamine. Unlike second-generation antihistamines, it crosses the blood-brain barrier — blockade of central H1 receptors explains the marked sedation.',
   'A difenidramina sofre metabolismo hepático de primeira passagem substancial, predominantemente pelo CYP2D6 (com vias pelo CYP3A4); os metabolitos (incluindo o N-desmetil) são eliminados na urina. A biodisponibilidade oral é de ~72%, refletindo o efeito de primeira passagem.',
   'Diphenhydramine undergoes substantial hepatic first-pass metabolism, predominantly by CYP2D6 (with CYP3A4 pathways); the metabolites (including N-desmethyl) are eliminated in the urine. Oral bioavailability is ~72%, reflecting the first-pass effect.',
   'A difenidramina é bem absorvida por via oral, com picos plasmáticos 1–3 horas após a dose; a ligação às proteínas plasmáticas é de ~80–85% e o volume de distribuição é de ~4,5 L/kg. Os efeitos antihistamínicos começam ~30 minutos após a toma.',
   'Diphenhydramine is well absorbed orally, with plasma peaks 1–3 hours after the dose; plasma protein binding is ~80–85% and the volume of distribution is ~4.5 L/kg. Antihistamine effects begin ~30 minutes after intake.',
   'A semivida média de eliminação é de ~8,4 horas em adultos (13,5 horas nos idosos; mais curta em crianças); a duração clínica do efeito é de 4–6 horas. A semivida prolonga-se na insuficiência hepática.',
   'The mean elimination half-life is ~8.4 hours in adults (13.5 hours in the elderly; shorter in children); the clinical duration of effect is 4–6 hours. Half-life is prolonged in hepatic impairment.',
   'Rótulo OTC DailyMed (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f1e83e43-011c-4470-bd55-fb2818a9fc84 — farmacocinética: PubMed PMID 3760245 (Pharmacokinetics of diphenhydramine and a demethylated metabolite, 1986); PMID 2391399 (Diphenhydramine: pharmacokinetics and pharmacodynamics in elderly, 1990)',
   'OTC DailyMed label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f1e83e43-011c-4470-bd55-fb2818a9fc84 — pharmacokinetics: PubMed PMID 3760245 (Pharmacokinetics of diphenhydramine and a demethylated metabolite, 1986); PMID 2391399 (Diphenhydramine: pharmacokinetics and pharmacodynamics in elderly, 1990)'),

  ('artesunato-amodiaquina',
   'Terapêutica combinada à base de artemisinina (ACT) de dose fixa com dupla ação antimalárica: o artesunato (pró-fármaco) elimina rapidamente a parasitemia por P. falciparum, e a amodiaquina, de ação mais prolongada, elimina os parasitas remanescentes. A eficácia na malária não complicada está estabelecida em ensaios clínicos; a maioria das reações adversas é semelhante aos sintomas do próprio acesso malárico.',
   'Fixed-dose artemisinin-based combination therapy (ACT) with dual antimalarial action: artesunate (prodrug) rapidly clears P. falciparum parasitaemia, and amodiaquine, with longer action, clears the remaining parasites. Efficacy in uncomplicated malaria is established in clinical trials; most adverse reactions resemble the symptoms of the malaria attack itself.',
   'O artesunato é um pró-fármaco rapidamente convertido em diidroartemisinina (DHA), que contém o anel endoperóxido responsável pela atividade: a clivagem do peróxido pelos iões de ferro do heme parasita gera radicais livres que danificam proteínas e membranas do parasita. A amodiaquina (4-aminoquinolina) acumula-se no vacúolo digestivo do parasita e inibe a polimerização da hemozoína (pigmento malárico), como a cloroquina, com atividade contra estirpes resistentes à cloroquina.',
   'Artesunate is a prodrug rapidly converted to dihydroartemisinin (DHA), which contains the endoperoxide ring responsible for activity: peroxide cleavage by iron ions from parasite haem generates free radicals that damage parasite proteins and membranes. Amodiaquine (4-aminoquinoline) accumulates in the parasite digestive vacuole and inhibits haemozoin (malaria pigment) polymerisation, like chloroquine, with activity against chloroquine-resistant strains.',
   'O artesunato é extensamente hidrolisado por esterases plasmáticas (e possivelmente pelo CYP2A6) em DHA, que é depois metabolizada por glucuronidação antes da excreção. A amodiaquine é extensamente metabolizada no fígado pelo CYP2C8 em desetilamodiaquina, o metabolito ativo principal, com semivida muito longa; apenas ~2% é excretada inalterada na urina.',
   'Artesunate is extensively hydrolysed by plasma esterases (and possibly CYP2A6) to DHA, which is then further metabolised by glucuronidation before excretion. Amodiaquine is extensively metabolised in the liver by CYP2C8 to desethylamodiaquine, the main active metabolite, with a very long half-life; only ~2% is excreted unchanged in urine.',
   'O artesunato é rapidamente absorvido (Tmax ~0,38 horas; Cmax ~185 ng/mL após dose única combinada) e a absorção é rápida para ambos os fármacos. Uma refeição rica em gordura diminui a Cmax e a AUC do artesunato (66% e 13%) mas aumenta as da amodiaquina (23% e 58%). A amodiaquina tem biodisponibilidade absoluta desconhecida; a desetilamodiaquina concentra-se 4–6 vezes mais no sangue total do que no plasma. O artesunato liga-se pouco às proteínas.',
   'Artesunate is rapidly absorbed (Tmax ~0.38 hours; Cmax ~185 ng/mL after a single combined dose) and absorption is rapid for both drugs. A high-fat meal decreases artesunate Cmax and AUC (66% and 13%) but increases those of amodiaquine (23% and 58%). Amodiaquine has unknown absolute bioavailability; desethylamodiaquine concentrates 4–6 times more in whole blood than in plasma. Artesunate is minimally protein bound.',
   'O artesunato tem semivida muito curta (~3–29 minutos; a DHA ~40–95 minutos). A desetilamodiaquina, o metabolito ativo da amodiaquina, é eliminada com semivida terminal de 9–18 dias, proporcionando a ação prolongada da terapêutica combinada; o volume de distribuição da amodiaquina é de 20–40 L/kg.',
   'Artesunate has a very short half-life (~3–29 minutes; DHA ~40–95 minutes). Desethylamodiaquine, the active metabolite of amodiaquine, is eliminated with a terminal half-life of 9–18 days, providing the prolonged action of the combination therapy; amodiaquine volume of distribution is 20–40 L/kg.',
   'SmPC WHO-prequalificada — Artesunate/Amodiaquine (Cipla, MA102), secção 5.2 Pharmacokinetic properties: https://extranet.who.int/prequal/sites/default/files/whopar_files/MA102part4.pdf',
   'WHO-prequalified SmPC — Artesunate/Amodiaquine (Cipla, MA102), section 5.2 Pharmacokinetic properties: https://extranet.who.int/prequal/sites/default/files/whopar_files/MA102part4.pdf')
) AS v(slug, pharmacodynamics_pt, pharmacodynamics_en, mechanism_pt, mechanism_en,
        metabolism_pt, metabolism_en, absorption_pt, absorption_en,
        half_life_pt, half_life_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;
